    public void SENTRYMOBILE_ValidateParkingSession(Map<String, String> objDictionary, IOSDriver iosDriver, String strStartTime, String strEndTime, String strTotalPayment) 
	{
	    IOS_Common_Flutter clsCommonMobile = new IOS_Common_Flutter();

	    // Time Variations
	    String startExact   = strStartTime;
	    String startPlus1   = clsCommonMobile.AddTimeToExistingTime(strStartTime, "+1", "MMM dd, hh:mm a");
	    String startMinus1  = clsCommonMobile.AddTimeToExistingTime(strStartTime, "-1", "MMM dd, hh:mm a");
	    String endExact     = strEndTime;
	    String endPlus1     = clsCommonMobile.AddTimeToExistingTime(strEndTime, "+1", "MMM dd, hh:mm a");
	    String endMinus1    = clsCommonMobile.AddTimeToExistingTime(strEndTime, "-1", "MMM dd, hh:mm a");

	    // Remaining Time
	    String strActualRemainingTimeMinutes = objDictionary.get("strActualRemainingTimeMinutes");
	    int totalMinutes = Integer.parseInt(strActualRemainingTimeMinutes);
	    int hours = totalMinutes / 60;
	    int mins  = totalMinutes % 60;

	    String remainingExact  = buildRemainingTimeString(hours, mins).replace(" h ", " h");
	    String remainingPlus1  = buildRemainingTimeString(hours, mins + 1).replace(" h ", " h");
	    String remainingMinus1 = buildRemainingTimeString(hours, mins - 1).replace(" h ", " h");

	    String spotName     = objDictionary.get("strMeterSpotName");
	    String licensePlate = objDictionary.get("strLicensePlateNumber").toUpperCase();

	    // Get actual text
	    String actualText = clsCommonMobile.StoreText(objDictionary, iosDriver, "Parking Sessions", "Parking Session Details", 1, "strActualParkingSessionDetails");
	    System.out.println("Actual  : " + actualText);
	    
	    // All combinations
	    String[] remainingOptions = { remainingExact, remainingPlus1, remainingMinus1 };
	    String[] startOptions     = { startExact, startPlus1, startMinus1 };
	    String[] endOptions       = { endExact, endPlus1, endMinus1 };

	    boolean matchFound = false;

	    for (String rem : remainingOptions) {
	        for (String st : startOptions) {
	            for (String en : endOptions) {
	                String expected = String.format(
	                    "Spot : %sSession ends in%sParked Time%sEnd Time%s%sTotal: %s",
	                    spotName, rem, st, en, licensePlate, strTotalPayment
	                );

	                System.out.println("Expected: " + expected);

	                if (actualText.contains(expected)) {
	                    Reporter.log("The Text (" + actualText + ") contained (" + expected + ")");
	                    objDictionary.put("strParkingSessionDetails", expected);
	                    objDictionary.put("strParkingSessionStart", st);
	                    matchFound = true;
	                    break;
	                }
	            }
	            if (matchFound) break;
	        }
	        if (matchFound) break;
	    }

	    // Fallback - both start and end minus 1
	    if (!matchFound) {
	        String bothMinus1 = String.format(
	            "Spot : %sSession ends in%sParked Time%sEnd Time%s%sTotal: %s",
	            spotName, remainingExact, startMinus1, endMinus1, licensePlate, strTotalPayment
	        );

	        if (actualText.contains(bothMinus1)) {
	            Reporter.log("The Text (" + actualText + ") contained (" + bothMinus1 + ")");
	            objDictionary.put("strParkingSessionDetails", bothMinus1);
	            objDictionary.put("strParkingSessionStart", startMinus1);
	            matchFound = true;
	        }
	    }

	    if (!matchFound) {
	        UpdateErrorMessageWithPivotalData(objDictionary, iosDriver,"The Text (" + actualText + ") did not match any expected parking session format.");
	    }
	}
    
