    public void SENTRYMOBILE_ValidateSubsequentPayment(Map<String, String> objDictionary,IOSDriver iosDriver)
	{
		Meter clsMeter = new Meter();
		IOS_Common_Flutter clsCommonMobile = new IOS_Common_Flutter();
		//Validate Subsequent Payment
	    String strMeterNextRateCost = clsMeter.GetMeterNextRateCost(objDictionary);
	 	double dblMeterNextRateCost = Double.parseDouble(strMeterNextRateCost) / 100;
	 	strMeterNextRateCost = "$" + String.format("%.2f", dblMeterNextRateCost);
	 	String strSubsequentPaymentTotal = clsCommonMobile.SENTRYMOBILE_ValidateSubsequentPaymentDialogAndReturnParkingFee(objDictionary, iosDriver, strMeterNextRateCost);
	    //Select Payment Option and Pay
	 	clsCommonMobile.PopulateScrollableListbox(objDictionary,iosDriver, "Review and Pay", "Select Payment Option", "FusionAI Mobile Account");
	 	clsCommonMobile.ClickButton(objDictionary, iosDriver, "Review and Pay", "Proceed", 1);
		String strStartTime = objDictionary.get("strParkingSessionStart");//SENTRYMOBILE_PurchaseMeterTimeParkThenPay
		String strMeterIncrementTime = objDictionary.get("strMeterIncrementTime");
		int intPurchasedTime = Integer.parseInt(strMeterIncrementTime) * 2;
		String strEndTime = clsCommonMobile.AddTimeToExistingTime(strStartTime, Integer.toString(intPurchasedTime),"MMM dd, hh:mm a");
		String strFreeTimeFirstPayment = objDictionary.get("strFreeTimeFirstPayment");
		//Add Free Time to End Time
  		if (!strFreeTimeFirstPayment.equals("")){strEndTime = clsCommonMobile.AddTimeToExistingTime(strEndTime, strFreeTimeFirstPayment,"MMM dd, hh:mm a");}
  		//Might want to pass this in.
	    String strCurrentMeterTime = "15";
	    String strRemainingFreeTimeStart = objDictionary.get("strRemainingFreeTimeStart");
	    String strTrueUpStartTime = objDictionary.get("strTrueUpStartTime");if(strTrueUpStartTime == null){strTrueUpStartTime = "";}
	    String strSessionReset = objDictionary.get("strSessionReset");if(strSessionReset == null){strSessionReset = "False";}
	    String strIncludePayment = objDictionary.get("strIncludePayment");if(strIncludePayment == null){strIncludePayment = "False";}
	    String strTrueUp = objDictionary.get("strTrueUp");if(strTrueUp == null){strTrueUp = "False";}
		String strViolationBonusPaymentAmount = objDictionary.get("strViolationBonusPaymentAmount");
		//Wait For Parking Session Details
		clsCommonMobile.GlobalWait(objDictionary, iosDriver, "Parking Sessions", "{TextExists} Parking Sessions~Parking Session Details", 80);
	 	//Calculate MeterRemainingTimeMinutes
		int intMeterRemainingTimeMinutes = 0;
		//Update with True-Up
		if(strTrueUpStartTime.equals("")||strSessionReset.equals("True"))
		{
			intMeterRemainingTimeMinutes = Integer.parseInt(strMeterIncrementTime) + Integer.parseInt(strFreeTimeFirstPayment) + Integer.parseInt(strMeterIncrementTime);
			if(strIncludePayment.equals("True"))
			{
				String strViolationBonusPaymentTime = objDictionary.get("strViolationBonusPaymentTime");
				int intUsedTime = 0;
				if(strTrueUp.equals("True")){intUsedTime = clsMeter.METER_CalculateUsedTime(objDictionary, null, strViolationBonusPaymentTime);}
					if(strViolationBonusPaymentAmount != null)
					{
						if(strSessionReset.equals("True"))
						{
							intMeterRemainingTimeMinutes = intMeterRemainingTimeMinutes + (Integer.parseInt(strViolationBonusPaymentAmount)/25 * Integer.parseInt(strMeterIncrementTime));
						}
						else
						{
							intMeterRemainingTimeMinutes = intMeterRemainingTimeMinutes + (Integer.parseInt(strViolationBonusPaymentAmount)/25 * Integer.parseInt(strMeterIncrementTime)) -intUsedTime;
						}
					}
					Reporter.log("***********Parking Time After Violation Reset With Payment*************");
						clsMeter.SENTRYMETER_StoreParkingSessionTime(objDictionary);
						Reporter.log("***********Parking Time After Violation Reset With Payment*************");
				}
				String strFreeTimeMinutes = objDictionary.get("strFreeTimeMinutes");if(strFreeTimeMinutes == null) {strFreeTimeMinutes = "0";}
				if(!strFreeTimeMinutes.equals("0"))
				{
					if(strRemainingFreeTimeStart != null)
					{
						//Free To Rate
						int intRemainingFreeTimeMinutes = clsMeter.METER_CalculateRemainingFreeTime(objDictionary, null, strRemainingFreeTimeStart, strFreeTimeMinutes);
						intMeterRemainingTimeMinutes = intMeterRemainingTimeMinutes + intRemainingFreeTimeMinutes;
						objDictionary.put("strRemainingFreeTimeMinutes", Integer.toString(intRemainingFreeTimeMinutes));
						String strPurchaseTime = objDictionary.get("strPurchaseTime");
						strEndTime = clsCommonMobile.AddTimeToExistingTime(strPurchaseTime, String.valueOf(intMeterRemainingTimeMinutes),"MMM dd, hh:mm a");
						System.out.println("MIH");
					}
					else
					{
						String strMinutesBeforeFreeStart = objDictionary.get("strMinutesBeforeFreeStart");
						intMeterRemainingTimeMinutes = clsMeter.METER_CalculateRemainingMinutesBeforeFree(objDictionary, null, strMinutesBeforeFreeStart);
						if(intMeterRemainingTimeMinutes > (Integer.parseInt(strMeterIncrementTime) * 2))
						{
							intMeterRemainingTimeMinutes = Integer.parseInt(strMeterIncrementTime) * 2;
						}
						strEndTime = clsCommonMobile.AddTimeToExistingTime(strStartTime, String.valueOf(intMeterRemainingTimeMinutes),"MMM dd, hh:mm a");
						objDictionary.put("strMeterRemainingTimeMinutes", Integer.toString(intMeterRemainingTimeMinutes));
					}
			  	}
			}
			else
			{
				intMeterRemainingTimeMinutes = clsMeter.METER_CalculateRemainingTrueUpTime(objDictionary, null,  strTrueUpStartTime, strMeterIncrementTime) + Integer.parseInt(strMeterIncrementTime) + Integer.parseInt(strFreeTimeFirstPayment);
			}
			//Validate Expected Meter Time
			clsMeter.METER_ValidateExpectedMeterTime(objDictionary, null, intMeterRemainingTimeMinutes, "1");
			//ValidateParkingSession
			String strFirstPaymentFee = objDictionary.get("strFirstPaymentFee");//SENTRYMOBILE_PurchaseMeterTimeParkThenPay
			String strSecondPaymentFee = objDictionary.get("strTotalFee");//SENTRYMOBILE_ValidateFirstPaymentDialogAndReturnParkingFee
			double dblFirstPaymentFee = Double.parseDouble(strFirstPaymentFee.replace("$", "").trim());
			double dblSecondPaymentFee = Double.parseDouble(strSecondPaymentFee.replace("$", "").trim());
			double dblTotalPayment = dblFirstPaymentFee + dblSecondPaymentFee;
			//Wait For Parking Session Details
        	clsCommonMobile.GlobalWait(objDictionary, iosDriver, "Parking Sessions", "{TextExists} Parking Sessions~Parking Session Details", 80);
        	//Subtract a minuted for used time
        	String strActualRemainingTimeMinutes = objDictionary.get("strActualRemainingTimeMinutes");
        	int intActualRemainingTimeMinutes = Integer.parseInt(strActualRemainingTimeMinutes);
        	objDictionary.put("strActualRemainingTimeMinutes",String.valueOf(intActualRemainingTimeMinutes));
        	//ValidateParkingSession
			clsCommonMobile.SENTRYMOBILE_ValidateParkingSession(objDictionary,iosDriver,strStartTime, strEndTime, String.format("$ %.2f", dblTotalPayment));
	}
    
    public void SENTRYMOBILE_MobilePaymentInitialPaymentMaxTime(Map<String, String> objDictionary, IOSDriver iosDriver)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		//Classes
		Meter clsMeter = new Meter();
		IOS_Common_Flutter clsCommonMobile = new IOS_Common_Flutter();
		//Dictionary Variables
	  	String strFreeDisconnectValue = objDictionary.get("strFreeDisconnectValue");if(strFreeDisconnectValue == null){strFreeDisconnectValue = "";}
	  	String strLicensePlateNumber = objDictionary.get("strLicensePlateNumber");
		String strLicensePlateState = objDictionary.get("strLicensePlateState");
	  	clsCommonMobile.SENTRYMOBILE_LoginOrRegisterWithRememberMeOffEmailIdWithoutCaps(objDictionary, iosDriver, "parker","Enroll later");
  		Reporter.log("strLicensePlateNumber: "+strLicensePlateNumber+"");
    	//ClickPermissionAlertButton
      	try {Thread.sleep(3000);}catch (Exception e) {}
      	clsCommonMobile.ClickPermissionAlertButton(objDictionary, iosDriver, "Allow");
      	try {Thread.sleep(2000);}catch (Exception e) {}
      	clsCommonMobile.ClickPermissionAlertButton(objDictionary, iosDriver, "Allow While Using App");
	  	//Wait for GPS Map to Load
		clsCommonMobile.SENTRYMOBILE_Populate_MeterPayment_SelectSpot(objDictionary,iosDriver,"1");
     	clsCommonMobile.SENTRYMOBILE_AddOrSelectLicensePlate(objDictionary, iosDriver, strLicensePlateNumber, strLicensePlateState);
     	//Validate Max Time
     	String strMeterMaxTime = clsMeter.GetMeterMaxTime(objDictionary, null,"1");
     	String strFreeTimeMinutes = objDictionary.get("strFreeTimeMinutes");
     	int intMeterMaxTime = Integer.parseInt(strMeterMaxTime);
     	if(strFreeTimeMinutes != null)
     	{
     		String strRemainingFreeTimeStart = objDictionary.get("strRemainingFreeTimeStart");
     		if(strRemainingFreeTimeStart != null)
     		{
	     		int intRemainingFreeTimeMinutes = clsMeter.METER_CalculateRemainingFreeTime(objDictionary, null, strRemainingFreeTimeStart, strFreeTimeMinutes);
	     		intMeterMaxTime = intMeterMaxTime - intRemainingFreeTimeMinutes;
	     		objDictionary.put("strRemainingFreeTimeMinutes",Integer.toString(intRemainingFreeTimeMinutes));
     		}
     		else
     		{
     			String strMinutesBeforeFreeStart = objDictionary.get("strMinutesBeforeFreeStart");
				int intMeterRemainingTimeMinutes = clsMeter.METER_CalculateRemainingMinutesBeforeFree(objDictionary, null, strMinutesBeforeFreeStart);
				objDictionary.put("strMeterRemainingTimeMinutes", Integer.toString(intMeterRemainingTimeMinutes));
     		}
		}
     	//Subtract Free Time
     	clsCommonMobile.VALIDATIONS_MeterPayment_MaxTime(objDictionary, iosDriver, 0, intMeterMaxTime,0);
     	//BMT: Buy Max Time
		clsCommonMobile.SENTRYMOBILE_BuyMaxTime(objDictionary, iosDriver, Integer.parseInt(strMeterMaxTime),"1");
	}
    
    public String SENTRYMOBILE_BuyMaxTime(Map<String, String> objDictionary,IOSDriver iosDriver, int intTotalMaxTimeMin,String strPaymentNbr)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		IOS_Common_Flutter clsCommonMobile = new IOS_Common_Flutter();
    	Meter clsMeter = new Meter();
    	HttpConnections clsHttpConnections = new HttpConnections();
		clsCommonMobile.ClickButton(objDictionary, iosDriver, "Choose Parking Duration", "Buy Max Time", 1);
		clsCommonMobile.ClickButton(objDictionary, iosDriver, "Choose Parking Duration", "Proceed", 1);
		//Validate Total Amount
		String strMeterNextRateCost = clsMeter.GetMeterNextRateCost(objDictionary);
		String strFreeTimeFirstPayment = objDictionary.get("strFreeTimeFirstPayment");
		String strSecondRateStartTime = objDictionary.get("strSecondRateStartTime");
		String strMeterIncrementTime = objDictionary.get("strMeterIncrementTime");
		DecimalFormat dFormat = new DecimalFormat("$ 0.00");
		//Check For Fees
		try {clsHttpConnections.HTTPCONNECTIONS_StoreMobileTransactionFees(objDictionary);}catch (Exception e) {}
		String strTotalFee = "0";
		if(strPaymentNbr.equals("1"))
		{
			String strFirstPayment = objDictionary.get("strFirstPayment");//First Payment Fee
			//intTotalMaxTimeMin = (int)Math.ceil(intTotalMaxTimeMin/Double.parseDouble(strMeterIncrementTime)) * Integer.parseInt(strMeterIncrementTime);
			if (strFirstPayment != null)
			{
				//strSecondRateStartTime comes from: SENTRYLINK_SetRateBlocksRateToRate - Not sure how it's used
				if(strSecondRateStartTime != null)
				{
					int intRemainingMinutesInFirstRateSet = clsMeter.METER_CalculateRemainingMinutesBeforeNextRate(objDictionary, null, strSecondRateStartTime)-Integer.parseInt(strFreeTimeFirstPayment);
					Reporter.log("Remaining Minutes First Rateblock: "+intRemainingMinutesInFirstRateSet);
					int intNumberOfPaymentInFirsttRateSet = intRemainingMinutesInFirstRateSet/12;
					int intRemainingMinutes = intRemainingMinutesInFirstRateSet - intNumberOfPaymentInFirsttRateSet * 12;
					Reporter.log("intRemainingMinutes: "+intRemainingMinutes);
					String strTotalFeeFirstRateSet = "$" + dFormat.format((int)Math.ceil(((double)intRemainingMinutesInFirstRateSet)/ Integer.parseInt(strMeterIncrementTime)) * (Double.parseDouble(strMeterNextRateCost)/100));
					Reporter.log("The Total Fee for the 1st Rate Block Equaled: "+strTotalFeeFirstRateSet);
					int intMinutesInSecondRateSet = intTotalMaxTimeMin - intRemainingMinutesInFirstRateSet-Integer.parseInt(strFreeTimeFirstPayment);
					Reporter.log("Remaining Minutes Second Rateblock: "+intMinutesInSecondRateSet);
					String strTotalFeeSecondRateSet = "$" + dFormat.format((int)Math.ceil(((double)intMinutesInSecondRateSet)/ 10) * (Double.parseDouble(strMeterNextRateCost)/100));
					Reporter.log("The Total Fee for the 2nd Rate Block Equaled: "+strTotalFeeSecondRateSet);
					String strFirstTimePaymentFee = "$" + dFormat.format((Integer.parseInt(strFirstPayment)*.01));
					Reporter.log("First Payment Fee: "+strFirstTimePaymentFee);
					objDictionary.put("strFirstTimePaymentFee",strFirstTimePaymentFee);//Used SENTRYMOBILE_PurchaseRemainingTime_ValidateParkingSessionValues
					strTotalFee = "$" + dFormat.format((int)Math.ceil(((double)intRemainingMinutesInFirstRateSet)/ Integer.parseInt(strMeterIncrementTime)) * (Double.parseDouble(strMeterNextRateCost)/100) + (int)Math.ceil(((double)intMinutesInSecondRateSet)/ 10) * (Double.parseDouble(strMeterNextRateCost)/100) + Integer.parseInt(strFirstPayment)*.01);
				}
				else
				{
					String strFreeTimeMinutes = objDictionary.get("strFreeTimeMinutes");
					String strRemainingFreeTimeStart = objDictionary.get("strRemainingFreeTimeStart");
		    		if(strRemainingFreeTimeStart != null)
		    		{
						int intRemainingFreeMinutes = clsMeter.METER_CalculateRemainingFreeTimeCeil(objDictionary, null,  strRemainingFreeTimeStart, strFreeTimeMinutes);
			    		clsCommonMobile.VerificationPointText(objDictionary, iosDriver, "Review and Pay", "Parking Fee", 1, "Contains", dFormat.format((intTotalMaxTimeMin -  Integer.parseInt(strFreeTimeFirstPayment)-intRemainingFreeMinutes)/ Integer.parseInt(strMeterIncrementTime) * (Double.parseDouble(strMeterNextRateCost)/100)));
						clsCommonMobile.VerificationPointText(objDictionary, iosDriver, "Review and Pay", "Convenience Fee", 1, "Contains", dFormat.format(Integer.parseInt(strFirstPayment)*.01));
						strTotalFee = dFormat.format((intTotalMaxTimeMin -  Integer.parseInt(strFreeTimeFirstPayment) - intRemainingFreeMinutes)/ Integer.parseInt(strMeterIncrementTime) * (Double.parseDouble(strMeterNextRateCost)/100)+ (Integer.parseInt(strFirstPayment)*.01));
		    		}
		    		else
		    		{
		    			String strMinutesBeforeFreeStart = objDictionary.get("strMinutesBeforeFreeStart");
		    			if(strMinutesBeforeFreeStart != null)
		    			{
		    				int intMeterRemainingTimeMinutes = clsMeter.METER_CalculateRemainingMinutesBeforeFree(objDictionary, null, strMinutesBeforeFreeStart);
							String strParkingFee = dFormat.format(Math.ceil(intMeterRemainingTimeMinutes / (double) Integer.parseInt(strMeterIncrementTime))* (Double.parseDouble(strMeterNextRateCost) / 100));
							clsCommonMobile.VerificationPointText(objDictionary, iosDriver, "Review and Pay", "Parking Fee", 1, "Contains", strParkingFee);
							clsCommonMobile.VerificationPointText(objDictionary, iosDriver, "Review and Pay", "Convenience Fee", 1, "Contains", dFormat.format(Integer.parseInt(strFirstPayment)*.01));
							strTotalFee = dFormat.format(Math.ceil(intMeterRemainingTimeMinutes / (double) Integer.parseInt(strMeterIncrementTime))* (Double.parseDouble(strMeterNextRateCost) / 100)+ (Integer.parseInt(strFirstPayment)*.01));
						 	objDictionary.put("strMeterRemainingTimeMinutes", Integer.toString(intMeterRemainingTimeMinutes));
		    			}
					 	else
						{
					 		clsCommonMobile.VerificationPointText(objDictionary, iosDriver, "Review and Pay", "Parking Fee", 1, "Contains", dFormat.format((intTotalMaxTimeMin -  Integer.parseInt(strFreeTimeFirstPayment))/ Integer.parseInt(strMeterIncrementTime) * (Double.parseDouble(strMeterNextRateCost)/100)));
							clsCommonMobile.VerificationPointText(objDictionary, iosDriver, "Review and Pay", "Convenience Fee", 1, "Contains", dFormat.format(Integer.parseInt(strFirstPayment)*.01));
							strTotalFee = dFormat.format((intTotalMaxTimeMin -  Integer.parseInt(strFreeTimeFirstPayment))/ Integer.parseInt(strMeterIncrementTime) * (Double.parseDouble(strMeterNextRateCost)/100)+ (Integer.parseInt(strFirstPayment)*.01));
						}
		    		}
				}
			}
			else
			{
				if(strSecondRateStartTime != null)
				{
					int intRemainingMinutesInFirstRateSet = clsMeter.METER_CalculateRemainingMinutesBeforeNextRate(objDictionary, null, strSecondRateStartTime)-Integer.parseInt(strFreeTimeFirstPayment);
					Reporter.log("Remaining Minutes First Rateblock: "+intRemainingMinutesInFirstRateSet);
					int intMinutesInSecondRateSet = intTotalMaxTimeMin - intRemainingMinutesInFirstRateSet;
					Reporter.log("Remaining Minutes Second Rateblock: "+intMinutesInSecondRateSet);

					String strTotalFeeFirstRateSet = "$" + dFormat.format((intRemainingMinutesInFirstRateSet)/ Integer.parseInt(strMeterIncrementTime) * (Double.parseDouble(strMeterNextRateCost)/100));
					Reporter.log("The Total Fee for the 1st Rate Block Equaled: "+strTotalFeeFirstRateSet);

					String strTotalFeeSecondRateSet = "$" + dFormat.format((intMinutesInSecondRateSet)/ 10 * (Double.parseDouble(strMeterNextRateCost)/100));
					Reporter.log("The Total Fee for the 2nd Rate Block Equaled: "+strTotalFeeSecondRateSet);
					strTotalFee = "$" + dFormat.format(((intRemainingMinutesInFirstRateSet)/ Integer.parseInt(strMeterIncrementTime) + (intMinutesInSecondRateSet)/ 10) * (Double.parseDouble(strMeterNextRateCost)/100));
				}
				else
				{
					strTotalFee = dFormat.format((intTotalMaxTimeMin -  Integer.parseInt(strFreeTimeFirstPayment))/ Integer.parseInt(strMeterIncrementTime) * (Double.parseDouble(strMeterNextRateCost)/100));
				}
			}
			clsCommonMobile.VerificationPointText(objDictionary, iosDriver, "Review and Pay", "Total Fee", 1, "Contains", strTotalFee);
		}
		else
		{
			String strSubsequentPayment = objDictionary.get("strSubsequentPayment");
			intTotalMaxTimeMin = (int)Math.ceil(intTotalMaxTimeMin/Double.parseDouble(strMeterIncrementTime)) * Integer.parseInt(strMeterIncrementTime);
			if (strSubsequentPayment != null)
			{strTotalFee = "$" + dFormat.format(intTotalMaxTimeMin / Integer.parseInt(strMeterIncrementTime) * Integer.parseInt(strMeterNextRateCost)/100 + (Integer.parseInt(strSubsequentPayment)*.01));}
			else
			{
				strTotalFee = "$" + dFormat.format(intTotalMaxTimeMin / Double.parseDouble(strMeterIncrementTime) * Double.parseDouble(strMeterNextRateCost)/100);
			}
			clsCommonMobile.VerificationPointText(objDictionary, iosDriver, "Review and Pay", "Total Fee", 1, "Contains", strTotalFee);
		}
		objDictionary.put("strTotalFee",strTotalFee);//Used SENTRYMOBILE_PurchaseRemainingTime_ValidateParkingSessionValues//SENTRYMOBILE_BuyMaxTime
		return strTotalFee;
	}
    
