	    clsCommonMobile.SENTRYMOBILE_AddOrSelectLicensePlate(objDictionary, iosDriver, strLicensePlateNumber, strState);
		clsCommonMobile.ClickButton(objDictionary, iosDriver, "Choose Parking Duration", "Proceed", 1);
