	private static final String IOS_SETTINGS_PRIVACY_SEARCH_QUERY = "Privacy & Security";

	/** Visible Settings toolbar search field (iOS 17+ applicationSearch can expose multiple Search nodes). */
	private WebElement iosFindVisibleSettingsSearchField(IOSDriver iosdriver) {
		String[] xpaths = {
				"//XCUIElementTypeSearchField[(@name='Search' or @label='Search')]",
				"//XCUIElementTypeSearchField[@type='XCUIElementTypeSearchField']"
		};
		for (int attempt = 0; attempt < 8; attempt++) {
			for (String xpath : xpaths) {
				List<WebElement> fields = iosdriver.findElements(By.xpath(xpath));
				for (WebElement field : fields) {
					try {
						if (field.isDisplayed() && field.isEnabled()) {
							return field;
						}
					} catch (Exception ignored) {
					}
				}
			}
			iosGpsSleep(400);
		}
		return null;
	}

	private WebElement iosFindPrivacyAndSecuritySearchResult(IOSDriver iosdriver) {
		String[] xpaths = {
				"//XCUIElementTypeButton[contains(@name,'OpenPrivacyAndSecuritySettingsDeepLink') and @label='Privacy & Security']",
				"//XCUIElementTypeButton[contains(@name,'OpenPrivacyAndSecuritySettingsDeepLink.PrivacyAndSecuritySettingsDeepLink')]",
				"//XCUIElementTypeButton[@name='Privacy & Security' and @label='Privacy & Security']",
				"//XCUIElementTypeButton[@name='Privacy & Security']"
		};
		for (int attempt = 0; attempt < 10; attempt++) {
			for (String xpath : xpaths) {
				List<WebElement> buttons = iosdriver.findElements(By.xpath(xpath));
				for (WebElement button : buttons) {
					try {
						if (button.isDisplayed() && button.isEnabled()) {
							return button;
						}
					} catch (Exception ignored) {
					}
				}
			}
			try {
				List<WebElement> byId = iosdriver.findElements(By.id("Privacy & Security"));
				for (WebElement button : byId) {
					if (button.isDisplayed() && button.isEnabled()) {
						return button;
					}
				}
			} catch (Exception ignored) {
			}
			iosGpsSleep(400);
		}
		return null;
	}

	private void iosRevealSettingsSearchIfNeeded(IOSDriver iosdriver) {
		if (iosFindVisibleSettingsSearchField(iosdriver) != null) {
			return;
		}
		for (int attempt = 0; attempt < 6; attempt++) {
			SwipeDown(iosdriver);
			iosGpsSleep(800);
			if (iosFindVisibleSettingsSearchField(iosdriver) != null) {
				return;
			}
		}
	}

	private void iosPopulateSettingsSearchForPrivacy(IOSDriver iosdriver, WebElement search) {
		String existing = "";
		try {
			String value = search.getAttribute("value");
			if (value != null && !value.isEmpty()) {
				existing = value.trim();
			}
		} catch (Exception ignored) {
		}
		if (existing.isEmpty()) {
			try {
				existing = search.getText() == null ? "" : search.getText().trim();
			} catch (Exception ignored) {
			}
		}
		if (IOS_SETTINGS_PRIVACY_SEARCH_QUERY.equalsIgnoreCase(existing)) {
			Reporter.log("Settings search already contains '" + IOS_SETTINGS_PRIVACY_SEARCH_QUERY + "'");
			return;
		}
		try {
			search.click();
		} catch (Exception ignored) {
		}
		try {
			search.clear();
		} catch (Exception ignored) {
		}
		search.sendKeys(IOS_SETTINGS_PRIVACY_SEARCH_QUERY);
		iosGpsSleep(2000);
	}

	private void iosTapPrivacyAndSecurityFromSearchResults(IOSDriver iosdriver) {
		WebElement privacyResult = iosFindPrivacyAndSecuritySearchResult(iosdriver);
		if (privacyResult == null) {
			throw new IllegalStateException(
					"Privacy & Security search result not found (expected OpenPrivacyAndSecuritySettingsDeepLink or "
							+ "button name/label 'Privacy & Security')");
		}
		privacyResult.click();
		Reporter.log("Privacy & Security search result was tapped");
		iosGpsSleep(2000);
	}

	private void iosTapLocationServicesSettingsEntry(IOSDriver iosdriver) {
		String[] xpaths = {
				"//XCUIElementTypeButton[@name='LOCATION']",
				"//XCUIElementTypeCell[@name='Location Services']",
				"//XCUIElementTypeButton[@name='Location Services']",
				"//XCUIElementTypeStaticText[@name='Location Services']/ancestor::XCUIElementTypeCell[1]"
		};
		for (int attempt = 0; attempt < 10; attempt++) {
			for (String xpath : xpaths) {
				List<WebElement> entries = iosdriver.findElements(By.xpath(xpath));
				for (WebElement entry : entries) {
					try {
						if (entry.isDisplayed() && entry.isEnabled()) {
							entry.click();
							Reporter.log("Location Services Settings entry was tapped");
							iosGpsSleep(2000);
							return;
						}
					} catch (Exception ignored) {
					}
				}
			}
			try {
				List<WebElement> byId = iosdriver.findElements(By.id("Location Services"));
				for (WebElement entry : byId) {
					if (entry.isDisplayed() && entry.isEnabled()) {
						entry.click();
						Reporter.log("Location Services Settings entry was tapped (id)");
						iosGpsSleep(2000);
						return;
					}
				}
			} catch (Exception ignored) {
			}
			iosGpsSleep(400);
		}
		throw new IllegalStateException("Location Services entry not found under Privacy & Security");
	}

	private boolean iosIsOnPrivacyAndSecurityPage(IOSDriver iosdriver) {
		try {
			List<WebElement> nav = iosdriver.findElements(
					By.xpath("//XCUIElementTypeNavigationBar[@name='Privacy & Security']"));
			return !nav.isEmpty();
		} catch (Exception ignored) {
			return false;
		}
	}

	private void iosNavigateSettingsToPrivacyLocation(Map<String, String> objDictionary, IOSDriver iosdriver) throws Exception {
		if (iosIsOnLocationServicesPage(iosdriver)) {
			Reporter.log("Already on Location Services Settings page - skipped Privacy navigation");
			return;
		}
		if (iosIsOnPrivacyAndSecurityPage(iosdriver)) {
			iosTapLocationServicesSettingsEntry(iosdriver);
			return;
		}
		WebElement readyPrivacyResult = iosFindPrivacyAndSecuritySearchResult(iosdriver);
		if (readyPrivacyResult != null) {
			iosTapPrivacyAndSecurityFromSearchResults(iosdriver);
			iosTapLocationServicesSettingsEntry(iosdriver);
			return;
		}
		iosRevealSettingsSearchIfNeeded(iosdriver);
		WebElement search = iosFindVisibleSettingsSearchField(iosdriver);
		if (search == null) {
			throw new IllegalStateException(
					"Settings search field not found (expected XCUIElementTypeSearchField name/label 'Search')");
		}
		iosPopulateSettingsSearchForPrivacy(iosdriver, search);
		iosGpsSleep(1500);
		iosTapPrivacyAndSecurityFromSearchResults(iosdriver);
		iosGpsSleep(1000);
		iosTapLocationServicesSettingsEntry(iosdriver);
	}

	private static final String IOS_LOCATION_SERVICES_TURN_OFF_ACCEPT_SELECTOR =
			"**/XCUIElementTypeButton[`name == \"Turn Off\" OR label == \"Turn Off\"`]";

	private WebElement iosLocationServicesMasterRow(IOSDriver iosdriver) {
		// Prefer the nested/leaf switch under the named Location Services control. The outer named
		// switch can expose value=1 but not actually toggle (Appium log: click 200, value stays 1,
		// no Turn Off sheet). Fall back to the named/label switch when no child exists.
		List<WebElement> nested = iosdriver.findElements(By.xpath(
				"//XCUIElementTypeSwitch[@name='Location Services']//XCUIElementTypeSwitch"));
		if (nested.isEmpty()) {
			nested = iosdriver.findElements(By.xpath(
					"//XCUIElementTypeSwitch[@label='Location Services']//XCUIElementTypeSwitch"));
		}
		if (!nested.isEmpty()) {
			return nested.get(nested.size() - 1);
		}
		List<WebElement> switches = iosdriver.findElements(
				By.xpath("//XCUIElementTypeSwitch[@name='Location Services']"));
		if (!switches.isEmpty()) {
			return switches.get(0);
		}
		switches = iosdriver.findElements(
				By.xpath("//XCUIElementTypeSwitch[@label='Location Services']"));
		if (!switches.isEmpty()) {
			return switches.get(0);
		}
		return null;
	}

	private String iosLocationServicesSwitchValue(WebElement row) {
		if (row == null) {
			return null;
		}
		try {
			String value = row.getAttribute("value");
			if (value != null && !value.isEmpty()) {
				return value;
			}
		} catch (Exception ignored) {
		}
		try {
			return row.getText();
		} catch (Exception ignored) {
			return null;
		}
	}

	private boolean iosIsOnLocationServicesPage(IOSDriver iosdriver) {
		try {
			List<WebElement> nav = iosdriver.findElements(
					By.xpath("//XCUIElementTypeNavigationBar[@name='Location Services']"));
			if (!nav.isEmpty()) {
				return true;
			}
		} catch (Exception ignored) {
		}
		return iosLocationServicesMasterRow(iosdriver) != null;
	}

	private String iosGetAcceptAlertButtonSelector(IOSDriver iosdriver) {
		try {
			Map<String, Object> settings = iosdriver.getSettings();
			if (settings != null && settings.get("acceptAlertButtonSelector") != null) {
				return String.valueOf(settings.get("acceptAlertButtonSelector"));
			}
		} catch (Exception ignored) {
		}
		return "";
	}

	private void iosRestoreAcceptAlertButtonSelector(IOSDriver iosdriver, String previousSelector) {
		try {
			iosdriver.setSetting("acceptAlertButtonSelector", previousSelector == null ? "" : previousSelector);
		} catch (Exception restoreEx) {
			System.out.println("Failed to restore acceptAlertButtonSelector: "
					+ restoreEx.getClass().getSimpleName() + ": " + restoreEx.getMessage());
		}
	}

	/**
	 * Confirms the Location Services "Turn Off" sheet. Does not use OK or generic alert.accept(),
	 * which can cancel with autoAcceptAlerts / WDA defaultAlertAction=accept.
	 */
	private boolean iosDismissLocationServicesTurnOffSheet(IOSDriver iosdriver) {
		for (int attempt = 0; attempt < 6; attempt++) {
			try {
				List<WebElement> buttons = iosdriver.findElements(By.xpath(
						"//XCUIElementTypeButton[@name='Turn Off' or @label='Turn Off']"));
				for (WebElement button : buttons) {
					try {
						if (button.isDisplayed()) {
							button.click();
							Reporter.log("'Turn Off' confirmation was clicked");
							iosGpsSleep(1500);
							return true;
						}
					} catch (Exception ignored) {
					}
				}
			} catch (Exception ignored) {
			}
			try {
				HashMap<String, Object> alertArgs = new HashMap<>();
				alertArgs.put("action", "accept");
				alertArgs.put("buttonLabel", "Turn Off");
				iosdriver.executeScript("mobile: alert", alertArgs);
				Reporter.log("Location Services turn-off confirmed via mobile: alert buttonLabel=Turn Off");
				iosGpsSleep(1500);
				return true;
			} catch (Exception ignored) {
			}
			iosGpsSleep(400);
		}
		return false;
	}

	private void iosEnableLocationServicesMaster(IOSDriver iosdriver) {
		WebElement row = iosLocationServicesMasterRow(iosdriver);
		if (row == null) {
			throw new IllegalStateException("Location Services master switch not found");
		}
		String val = iosLocationServicesSwitchValue(row);
		if ("0".equals(val)) {
			row.click();
			Reporter.log("Location Services was enabled");
			iosGpsSleep(2000);
			row = iosLocationServicesMasterRow(iosdriver);
			val = iosLocationServicesSwitchValue(row);
		} else if ("1".equals(val)) {
			Reporter.log("Location Services was already enabled");
		} else {
			throw new IllegalStateException("Location Services switch value unexpected: '" + val + "'");
		}
		if (!"1".equals(val)) {
			throw new IllegalStateException("Failed to enable Location Services; final value='" + val + "'");
		}
	}

	private void iosDisableLocationServicesMaster(IOSDriver iosdriver) {
		String previousAcceptSelector = iosGetAcceptAlertButtonSelector(iosdriver);
		boolean selectorChanged = false;
		try {
			try {
				iosdriver.setSetting("acceptAlertButtonSelector", IOS_LOCATION_SERVICES_TURN_OFF_ACCEPT_SELECTOR);
				selectorChanged = true;
				Reporter.log("acceptAlertButtonSelector set to Turn Off for Location Services disable");
			} catch (Exception setEx) {
				System.out.println("Unable to set acceptAlertButtonSelector before Location Services disable: "
						+ setEx.getClass().getSimpleName() + ": " + setEx.getMessage());
			}

			WebElement row = iosLocationServicesMasterRow(iosdriver);
			if (row == null) {
				throw new IllegalStateException("Location Services master switch not found");
			}
			String val = iosLocationServicesSwitchValue(row);
			if ("1".equals(val)) {
				row.click();
				Reporter.log("Location Services switch was clicked to disable");
				iosGpsSleep(800);
				row = iosLocationServicesMasterRow(iosdriver);
				val = iosLocationServicesSwitchValue(row);
				if (!"0".equals(val)) {
					boolean confirmed = iosDismissLocationServicesTurnOffSheet(iosdriver);
					System.out.println("Location Services Turn Off confirmation attempted=" + confirmed);
					iosGpsSleep(1200);
					row = iosLocationServicesMasterRow(iosdriver);
					val = iosLocationServicesSwitchValue(row);
				} else {
					Reporter.log("Location Services already OFF after switch click (autoAccept/Turn Off selector)");
				}
			} else if ("0".equals(val)) {
				Reporter.log("Location Services was already disabled");
			} else {
				throw new IllegalStateException("Location Services switch value unexpected: '" + val + "'");
			}
			if (!"0".equals(val)) {
				throw new IllegalStateException("Failed to disable Location Services; final value='" + val + "'");
			}
		} finally {
			if (selectorChanged) {
				iosRestoreAcceptAlertButtonSelector(iosdriver, previousAcceptSelector);
			}
		}
	}

	private void iosReturnToSentryMobile(IOSDriver iosdriver) {
		iosdriver.runAppInBackground(Duration.ofSeconds(-1));
		// Reactivate whichever app this session installed (FusionAI or EasySpotPay)
		iosdriver.activateApp(iosSessionAppBundle);
	}
	/**
	 * Toggles the system Location Services master switch on a physical device via Settings UI.
	 * Skips Privacy navigation when already on the Location Services screen.
	 */
	private void iosSetLocationServicesMasterOnDevice(Map<String, String> objDictionary, IOSDriver iosdriver, boolean enable) {
		Exception primary = null;
		try {
			iosdriver.runAppInBackground(Duration.ofSeconds(-1));
			iosGpsSleep(1000);

			boolean alreadyOnPage = iosIsOnLocationServicesPage(iosdriver);
			if (!alreadyOnPage) {
				iosOpenSettingsFromHome(iosdriver);
				iosGpsSleep(1000);
				// Settings often reopens on the last visited page (Location Services).
				alreadyOnPage = iosIsOnLocationServicesPage(iosdriver);
			}
			if (!alreadyOnPage) {
				iosNavigateSettingsToPrivacyLocation(objDictionary, iosdriver);
			} else {
				Reporter.log("Already on Location Services Settings page - skipped navigation");
			}

			if (enable) {
				iosEnableLocationServicesMaster(iosdriver);
			} else {
				iosDisableLocationServicesMaster(iosdriver);
			}
		} catch (Exception e) {
			primary = e;
			throw new RuntimeException(
					"Failed to set Location Services master to " + (enable ? "ON" : "OFF") + ": " + e.getMessage(), e);
		} finally {
			try {
				iosReturnToSentryMobile(iosdriver);
			} catch (Exception restoreEx) {
				System.out.println("iosReturnToSentryMobile failed after Location Services toggle: "
						+ restoreEx.getClass().getSimpleName() + ": " + restoreEx.getMessage());
				if (primary == null) {
					throw new RuntimeException(
							"Location Services toggle succeeded but failed to return to app: " + restoreEx.getMessage(),
							restoreEx);
				}
			}
		}
	}

	// Last known Location Services master state is kept in objDictionary under "strLocationServicesLastState"
	// ("True"/"False"). BeforeMethod carries it across objDictionary.clear() so it survives app reinstalls.
	/**
	 * Returns true if the device can currently report a location (Location Services master is ON).
	 * Returns false if the call fails, which means OFF or that WebDriverAgent lacks location permission.
	 */
	private boolean iosProbeLocationServicesOn(IOSDriver iosdriver) {
		try {
			Object loc = iosdriver.getLocation();
			System.out.println("iosProbeLocationServicesOn: location=" + loc);
			return loc != null;
		} catch (Exception e) {
			System.out.println("iosProbeLocationServicesOn: location unavailable (" + e.getClass().getSimpleName() + ")");
			return false;
		}
	}
	/**
	 * Only opens Settings when the Location Services master switch isn't already in the wanted state.
	 * Uses the last known state from objDictionary first; for ON it also accepts a live location probe.
	 * Set strForceLocationSettings=True to always go through Settings.
	 * Caches the wanted state only after the Settings toggle is verified.
	 */
	private void iosEnsureLocationServicesMaster(Map<String, String> objDictionary, IOSDriver iosdriver, String strIOSUdid, boolean enable) {
		boolean force = "True".equalsIgnoreCase(objDictionary.getOrDefault("strForceLocationSettings", "False"));
		String strWanted = enable ? "True" : "False";
		String strLastState = objDictionary.get("strLocationServicesLastState");
		System.out.println("[" + strIOSUdid + "] Location Services last known state='" + strLastState + "', wanted='" + strWanted + "'");
		if (!force) {
			if (strWanted.equalsIgnoreCase(strLastState)) {
				Reporter.log("Location Services already " + (enable ? "ON" : "OFF") + " for " + strIOSUdid + " (last known state) - skipped Settings");
				return;
			}
			if (enable && strLastState == null && iosProbeLocationServicesOn(iosdriver)) {
				objDictionary.put("strLocationServicesLastState", "True");
				Reporter.log("Location Services already ON for " + strIOSUdid + " (probe) - skipped Settings");
				return;
			}
		}
		try {
			iosSetLocationServicesMasterOnDevice(objDictionary, iosdriver, enable);
			objDictionary.put("strLocationServicesLastState", strWanted);
		} catch (RuntimeException e) {
			objDictionary.remove("strLocationServicesLastState");
			throw e;
		}
	}

  	public void SENTRYMOBILE_SETGPSSettings(Map<String, String> objDictionary,IOSDriver iosdriver, String strGPSEnabled, String strLocation)
    {
  		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
  		System.out.println(strMethodName);
  		String strIOSUdid = objDictionary.get("strIOSUdid");
  		if (strIOSUdid == null && "mpsadmin".equals(objDictionary.get("strAutomationUser"))) {
  		    strIOSUdid = "c14f91a4a519bbcc8a8550ca21f60d2c42a940e0";
  		}
  		if (strIOSUdid == null) {
  			strIOSUdid = "";
  		}
  		objDictionary.put("strGPSEnabled",strGPSEnabled);
        if ("True".equals(strGPSEnabled))
		{
  			if (strIOSUdid.isEmpty())
  			{
	  			String[] arrLocationItems = strLocation.split(" ");
				double dblLatitude = Double.parseDouble(arrLocationItems[1]);
				double dblLongitude = Double.parseDouble(arrLocationItems[0]);
				SENTRYMOBILE_SetGPSCoordinates(dblLatitude, dblLongitude);
			}
  			else
  			{
  				iosEnsureLocationServicesMaster(objDictionary, iosdriver, strIOSUdid, true);
  			}
		}
		else
		{
			iosEnsureLocationServicesMaster(objDictionary, iosdriver, strIOSUdid, false);
			Reporter.log("Sentry Mobile was reloaded correctly on IOS Device");
			if (!strIOSUdid.isEmpty())
	    	{
				String strCondition = ConditionalStepText(objDictionary,iosdriver, "User Agreement", "Turn On Location Services to Allow “Sentry Mobile” to Determine Your Location", 1, "Exists", "");
				if (strCondition.equals("True"))
				{
			    	VerificationPointText(objDictionary, iosdriver,"User Agreement", "Turn On Location Services to Allow “Sentry Mobile” to Determine Your Location", 1, "Exists", "");
			    	ClickButton(objDictionary, iosdriver, "User Agreement", "Cancel", 1);
			    	strCondition = ConditionalStepText(objDictionary,iosdriver, "User Agreement", "“Sentry Mobile” Would Like to Send You Notifications", 1, "Exists", "");
			    	if (strCondition.equals("True"))
			    	{
				    	VerificationPointText(objDictionary, iosdriver,"User Agreement", "“Sentry Mobile” Would Like to Send You Notifications", 1, "Exists", "");
				       	ClickButton(objDictionary, iosdriver, "User Agreement", "Allow", 1);
			    	}
				}
	    	}
		}
    }

	public void SENTRYMOBILE_AddOrSelectLicensePlate(Map<String, String> objDictionary, IOSDriver iosDriver, String strLicensePlate, String strState)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		IOS_Common_Flutter clsCommonMobile = new IOS_Common_Flutter();
		HttpConnections clsHttpConnections = new HttpConnections();
		String strLicensePlateExists = "";
		try{strLicensePlateExists = clsHttpConnections.JsonCheckIfLicensePlatesExistsForUser(objDictionary, strLicensePlate,"parker");}catch (Exception e) {}
		if(strLicensePlateExists.equals("False"))
		{
			//Add License Plate
			clsCommonMobile.ClickButton(objDictionary, iosDriver,  "Select Your Vehicle", "Add a vehicle", 1);
			clsCommonMobile.PopulateAction(objDictionary, iosDriver, "Add a vehicle", "Populate License Plate", "{T} Plate",strLicensePlate);
			clsCommonMobile.PopulateScrollableListbox(objDictionary,iosDriver, "Add a vehicle", "Territory", strState);
			clsCommonMobile.ClickButton(objDictionary, iosDriver, "Add a vehicle", "Add Vehicle", 1);
		}
		clsCommonMobile.ClickButton(objDictionary, iosDriver, "Select Your Vehicle", "License Plate", 1);

	}
	public void SENTRYMOBILE_AddReportVariables(Map<String, String> objDictionary)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethodName+"</font>");
		Meter clsMeter = new Meter();
		HttpConnections clsHttpConnections = new HttpConnections();
  		try{clsHttpConnections.JsonStoreSentryVersion(objDictionary);}catch (Exception e) {}
  		//Add Test Case Name to IReporter Listner
  		String strTestSuiteName = objDictionary.get("strTestSuiteName");
  		String strTestCaseName = objDictionary.get("strTestCaseName");
		ITestResult ITResult = Reporter.getCurrentTestResult();
		ITResult.setAttribute("strTestCaseName", strTestCaseName);
		ITResult.setAttribute("strTestSuiteName", strTestSuiteName);
		objDictionary.put("strTestCaseName", strTestCaseName);
  		String strEnvironment = objDictionary.get("strEnvironment");
		String strHost = objDictionary.get("strHost");
		String strIOSDeviceName = objDictionary.get("strIOSDeviceName");
		String strIOSVersion = objDictionary.get("strIOSVersion");
		String strMeterName = objDictionary.get("strMeterName");
		String strMunicipality = objDictionary.get("strMunicipality");
		String strRemotePath = objDictionary.get("strRemotePath");
		String strVersion = "";
		String strMeterVersion = clsMeter.GetMeterVersion(objDictionary, null,"Local");
		String strMD5SUMVersion  = clsMeter.GetMeterMD5SUMVersion(objDictionary);
		String strSilverBulletVersion = clsMeter.SENTRYMETER_GetSilverBulletVersion(objDictionary);
		String strSentryLinkVersion = objDictionary.get("strSentryLinkVersion");
		String strMeterStartTime = objDictionary.get("strMeterStartTime");
		switch (strEnvironment)
		{
			case "QA":
				strVersion = "MPS_Quality_"+strIOSDeviceName+"_"+strIOSVersion+".app";
				break;
			case "SG":
				strVersion = "MPS_Stagging_"+strIOSDeviceName+"_"+strIOSVersion+".app";
				break;
		}
		objDictionary.remove("strIOSFullVersion");objDictionary.put("strIOSFullVersion", strVersion);
		Reporter.log("************************************************************");
		Reporter.log("Environment:  "+strEnvironment+"                            ");
		Reporter.log("Version:      "+strVersion+"                                ");
		Reporter.log("Municipality: "+strMunicipality+"                           ");
		Reporter.log("Meter Name:   "+strMeterName+"                              ");
		Reporter.log("Meter IP:     "+strHost+"                                   ");
		Reporter.log("Meter Version:"+strMeterVersion+"                           ");
		Reporter.log("Meter MD5SUM Version:"+strMD5SUMVersion+"                   ");
		Reporter.log("Sentry Link Version:"+strSentryLinkVersion+"                ");
		Reporter.log("SilverBullet Version:"+strSilverBulletVersion+"             ");
		Reporter.log("RemotePath:   "+strRemotePath+"                             ");
		Reporter.log("************************************************************");
		Reporter.log("<font color='green'>Meter Start Time "+strMeterStartTime+"</font>");
		clsMeter.METER_GetMemory(objDictionary,"Local");
	}

	public void SENTRYMOBILE_Open(Map<String, String> objDictionary, IOSDriver iosDriver)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethodName+"</font>");
		IOS_Common_Flutter clsCommonMobile = new IOS_Common_Flutter();
		//APNS received Notification
		try{iosDriver.findElement(By.name("OK")).click();}catch (Exception e) {}
		String strCondition = clsCommonMobile.ConditionalStepButton(objDictionary, iosDriver, "User Agreement", "OK", 1, "Exists", "");
		if(strCondition.equals("True"))
		{
			clsCommonMobile.ClickButton(objDictionary, iosDriver, "User Agreement", "OK",1);
		}
		strCondition = clsCommonMobile.ConditionalStepButton(objDictionary, iosDriver, "User Agreement", "Remind me later", 1, "Exists", "");
		if(strCondition.equals("True"))
		{
			clsCommonMobile.ClickButton(objDictionary, iosDriver, "User Agreement", "Remind me later",1);
			clsCommonMobile.ClickButton(objDictionary, iosDriver, "User Agreement", "OK",1);
		}
		clsCommonMobile.ClickButton(objDictionary, iosDriver, "User Agreement", "Accept",1);
	}

