	public String ConditionalStepLink(Map<String, String> objDictionary, IOSDriver iosdriver, String strPageName, String strLinkName, int intLinkIndex, String strValidationType, String strTextVaue)
    {
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		WebElement objLink = GetLinkObj(objDictionary, iosdriver, strPageName, strLinkName);
		if (objLink != null)
        {
            switch (strValidationType)
            {
                case "Disabled":
                    if (!objLink.isEnabled()) { return "True"; } else { return "False"; }
                case "Does Not Exist":
                    return "False";
                case "Enabled":
                    if (objLink.isEnabled()) { return "True"; } else { return "False"; }
                case "Exists":
                    return "True";
                case "Visible":
                    if (objLink.isDisplayed()) { return "True"; } else { return "False"; }
                case "Invisible":
                    if (objLink.isDisplayed()) { return "True"; } else { return "False"; }
                default:
                	UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The validation type (" + strValidationType + ") hasn't been coded yet-"+strMethodName);
            }
        }
        else
        {
            switch (strValidationType)
            {
                case "Does Not Exist":
                    return "True";
                case "Exists":
                    return "False";
                default:
                	UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,"The link (" + strLinkName + ") at index (" + intLinkIndex + ") did not exist, so it could not perform the (" + strValidationType + ") validation-"+strMethodName);
            }
        }
        return "";
    }
