    public void SwipeRightToLeftOnElement(IOSDriver iosdriver,WebElement element)
    {
    	//Right To Left
    	new TouchAction(iosdriver)
    	.press(PointOption.point(element.getLocation().getX() + (element.getSize().width - 20),element.getLocation().getY() + (element.getSize().height / 2)))
    	.waitAction(WaitOptions.waitOptions(Duration.ofMillis(3000)))
    	.moveTo(PointOption.point(element.getLocation().getX(),element.getLocation().getY() + (element.getSize().height / 2)))
    	.release().perform();
    }
