    public void startServer(Map<String, String> objDictionary) {
        String strDeviceAppiumPort = objDictionary.get("strDeviceAppiumPort");
        int port = Integer.parseInt(strDeviceAppiumPort != null ? strDeviceAppiumPort : "4723");

        String logFilePath = System.getProperty("user.dir") + "/appium_full.log";
        System.out.println("Appium logs will be written to: " + logFilePath);
        Reporter.log("Appium logs will be written to: " + logFilePath);

        try {
            // Clean up any previous service
            if (service != null && service.isRunning()) {
                service.stop();
                Thread.sleep(2000);
            }

            AppiumServiceBuilder builder = new AppiumServiceBuilder()
                    .withIPAddress("127.0.0.1")
                    .usingPort(port)
                    .withArgument(GeneralServerFlag.SESSION_OVERRIDE)
                    .withArgument(() -> "--allow-cors")           // ← This is the correct syntax
                    .withArgument(GeneralServerFlag.ALLOW_INSECURE, "*:session_discovery") // Lets Appium Inspector list and attach to running sessions (Appium 3)
                    .withArgument(GeneralServerFlag.LOG_LEVEL, "debug")
                    .withLogFile(new File(logFilePath))
                    .withTimeout(Duration.ofSeconds(30));

            service = AppiumDriverLocalService.buildService(builder);
            service.start();

            // Extra buffer so Inspector can reliably connect
            Thread.sleep(5000);

            Reporter.log("Appium server started successfully on port " + port + " (with --allow-cors)");
            System.out.println("✅ Appium server started on http://127.0.0.1:" + port + " with CORS enabled");

        } catch (Exception e) {
            e.printStackTrace();
            Reporter.log("Failed to start Appium server: " + e.getMessage());
            throw new RuntimeException("Appium server failed to start", e);
        }
    }
	public void stopServer(Map<String, String> objDictionary) {
	    try {
	        // First try graceful stop via the service object
	        if (service != null) {
	            if (service.isRunning()) {
	                service.stop();
	                System.out.println("Appium service stopped gracefully.");
	                Reporter.log("Appium service stopped gracefully.");
	            }
	            service = null;
	        }

	        // Aggressive fallback: kill ALL node processes on the exact port
	        String port = objDictionary.get("strDeviceAppiumPort");
	        if (port != null) {
	            String[] killCommand = {"sh", "-c", "lsof -ti:" + port + " | xargs kill -9"};
	            Runtime.getRuntime().exec(killCommand);
	            System.out.println("Killed any remaining processes on port " + port);
	            Reporter.log("Killed remaining Appium processes on port " + port);
	        }

	        Thread.sleep(3000); // Give OS time to release the port

	    } catch (Exception e) {
	        System.out.println("Error during stopServer: " + e.getMessage());
	        e.printStackTrace();
	    }
	}
    public String SubtractTimeToExistingTime(String strTime, String strPlusMinutes,String strDateFormat)
	{
		String newTime = "";
		try
		{
			DateFormat sdf = new SimpleDateFormat(strDateFormat);
			Date startDate = sdf.parse(strTime);
			Calendar cal = Calendar.getInstance();
			cal.setTime(startDate);
			cal.add(Calendar.MINUTE, -Integer.parseInt(strPlusMinutes));
			newTime = sdf.format(cal.getTime());
		}
		catch(Exception e) {}
		return newTime;
	}


