	public void SENTRYMOBILE_AssertLocationDegradedOrPrompt(Map<String, String> objDictionary, IOSDriver iosdriver, String strContext) {
		String source = SENTRYMOBILE_CaptureVisibleUi(iosdriver);
		if (NegativeInputCases.looksLikeLocationOrPermissionPrompt(source)) {
			Reporter.log("Location/permission prompt or degrade copy was shown after " + strContext);
			return;
		}
		if (SENTRYMOBILE_PageLooksLoggedIn(iosdriver) || NegativeInputCases.looksLikeLoginForm(source)) {
			Reporter.log("No explicit location dialog after " + strContext + "; app stayed on a usable screen");
			return;
		}
		UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,
				"Expected a location/permission prompt or a usable degraded screen after " + strContext);
	}

	public void SENTRYMOBILE_AssertOfflineOrAirplaneMessage(Map<String, String> objDictionary, IOSDriver iosdriver, String strContext) {
		String snackbar = objDictionary.get("strSnackbarText");
		if (snackbar == null) snackbar = "";
		String source = "";
		try { source = iosdriver.getPageSource(); } catch (Exception e) { source = ""; }
		String combined = (snackbar + " " + source).toLowerCase();
		if (combined.contains("airplane") || combined.contains("no internet") || combined.contains("offline")
				|| combined.contains("no network") || combined.contains("not connected")) {
			Reporter.log("Offline/airplane messaging was shown after " + strContext);
			return;
		}
		UpdateErrorMessageWithPivotalData(objDictionary, iosdriver,
				"Expected an offline or airplane-mode message after " + strContext + " - snackbar='" + snackbar + "'");
	}

	public void SENTRYMOBILE_AssertLoginWasNotBypassed(Map<String, String> objDictionary, IOSDriver iosdriver, String strContext) {
		String source = SENTRYMOBILE_CaptureVisibleUi(iosdriver);
		if (NegativeInputCases.looksLikeCrash(source)) {
			UpdateErrorMessageWithPivotalData(objDictionary, iosdriver, "App crashed after " + strContext);
			return;
		}
		if (NegativeInputCases.looksLikeLoggedIn(source) && !NegativeInputCases.looksLikeLoginForm(source)) {
			UpdateErrorMessageWithPivotalData(objDictionary, iosdriver, "Login succeeded unexpectedly after " + strContext);
			return;
		}
		Reporter.log("Still on a non-authenticated or login screen after " + strContext);
	}

	public void SENTRYMOBILE_AssertInjectionTreatedAsPlainText(Map<String, String> objDictionary, IOSDriver iosdriver, String payload, String strContext) {
		String source = SENTRYMOBILE_CaptureVisibleUi(iosdriver);
		if (NegativeInputCases.looksLikeScriptExecuted(source, payload)) {
			UpdateErrorMessageWithPivotalData(objDictionary, iosdriver, "Injection payload appeared to execute after " + strContext);
			return;
		}
		if (NegativeInputCases.injectionAppearsAsPlainText(source, payload)) {
			Reporter.log("Injection payload is still visible as plain text after " + strContext);
		} else {
			Reporter.log("Injection payload is not visible in the page source after " + strContext + " (validation message / rejected input is acceptable)");
		}
		SENTRYMOBILE_AssertLoginWasNotBypassed(objDictionary, iosdriver, strContext);
	}

	public void SENTRYMOBILE_SendKeysToLoginField(Map<String, String> objDictionary, IOSDriver iosdriver, String strFieldName, String value) {
		WebElement field = GetTextFieldObj(objDictionary, iosdriver, "Log in", strFieldName);
		if (field == null) {
			UpdateErrorMessageWithPivotalData(objDictionary, iosdriver, "Login field (" + strFieldName + ") was not found for sendKeys");
			return;
		}
		try {
			field.click();
			try { field.clear(); } catch (Exception e) {}
			field.sendKeys(value == null ? "" : value);
		} catch (Exception e) {
			UpdateErrorMessageWithPivotalData(objDictionary, iosdriver, "Could not sendKeys to Login " + strFieldName + ": " + e.getMessage());
		}
	}

	/**
	 * Fast entry for long login values: set the iOS pasteboard and paste into the focused field.
	 * Handles the "Allow Paste" permission alert if it appears. Falls back to sendKeys if paste fails.
	 * Logs which path was used and the readable field value length when available.
	 */
	public void SENTRYMOBILE_PasteIntoLoginField(Map<String, String> objDictionary, IOSDriver iosdriver, String strFieldName, String value) {
		WebElement field = GetTextFieldObj(objDictionary, iosdriver, "Log in", strFieldName);
		if (field == null) {
			UpdateErrorMessageWithPivotalData(objDictionary, iosdriver, "Login field (" + strFieldName + ") was not found for paste");
			return;
		}
		String text = value == null ? "" : value;
		try {
			field.click();
			try { field.clear(); } catch (Exception e) {}
		} catch (Exception e) {
			UpdateErrorMessageWithPivotalData(objDictionary, iosdriver, "Could not focus Login " + strFieldName + " for paste: " + e.getMessage());
			return;
		}
		boolean pasted = iosPasteIntoFocusedField(iosdriver, field, text);
		if (pasted && !iosLoginFieldLooksEmpty(field, text.length())) {
			Reporter.log("Entered Login " + strFieldName + " via pasteboard paste (" + text.length() + " chars)");
			iosLogLoginFieldValueLength(field, strFieldName, text.length());
			return;
		}
		if (pasted) {
			Reporter.log("Pasteboard paste was invoked for Login " + strFieldName + " but the field value was empty or unconfirmed; falling back to sendKeys");
		} else {
			Reporter.log("Pasteboard paste failed for Login " + strFieldName + "; falling back to sendKeys");
		}
		try {
			try { field.click(); } catch (Exception ignored) {}
			try { field.clear(); } catch (Exception ignored) {}
			field.sendKeys(text);
			Reporter.log("Entered Login " + strFieldName + " via sendKeys fallback (" + text.length() + " chars)");
			iosLogLoginFieldValueLength(field, strFieldName, text.length());
		} catch (Exception e) {
			UpdateErrorMessageWithPivotalData(objDictionary, iosdriver, "Could not paste or sendKeys to Login " + strFieldName + ": " + e.getMessage());
		}
	}

	private boolean iosPasteIntoFocusedField(IOSDriver iosdriver, WebElement field, String value) {
		try {
			Map<String, Object> args = new HashMap<>();
			args.put("content", Base64.getEncoder().encodeToString(value.getBytes(StandardCharsets.UTF_8)));
			args.put("contentType", "plaintext");
			args.put("encoding", "utf8");
			iosdriver.executeScript("mobile: setPasteboard", args);
			Reporter.log("Set the iOS pasteboard (" + value.length() + " chars, base64) via mobile: setPasteboard");
		} catch (Exception e) {
			Reporter.log("mobile: setPasteboard failed: " + e.getMessage());
			return false;
		}
		iosDismissPastePermissionIfPresent(iosdriver);
		try {
			iosLongPressElement(iosdriver, field, 900);
		} catch (Exception e) {
			Reporter.log("Long-press on the login field failed: " + e.getMessage());
		}
		iosDismissPastePermissionIfPresent(iosdriver);
		if (iosTapPasteMenuItem(iosdriver)) {
			iosDismissPastePermissionIfPresent(iosdriver);
			iosTapPasteMenuItem(iosdriver);
			return true;
		}
		try {
			org.openqa.selenium.Point loc = field.getLocation();
			org.openqa.selenium.Dimension size = field.getSize();
			int x = loc.getX() + Math.max(1, size.getWidth() / 2);
			int y = loc.getY() + Math.max(1, size.getHeight() / 2);
			iosW3cTap(iosdriver, x, y);
			try { Thread.sleep(80); } catch (Exception ignored) {}
			iosW3cTap(iosdriver, x, y);
		} catch (Exception e) {
			Reporter.log("Double-tap on the login field failed: " + e.getMessage());
		}
		iosDismissPastePermissionIfPresent(iosdriver);
		if (iosTapPasteMenuItem(iosdriver)) {
			iosDismissPastePermissionIfPresent(iosdriver);
			iosTapPasteMenuItem(iosdriver);
			return true;
		}
		return false;
	}

	private void iosLongPressElement(IOSDriver iosdriver, WebElement field, int durationMs) {
		org.openqa.selenium.Point loc = field.getLocation();
		org.openqa.selenium.Dimension size = field.getSize();
		int x = loc.getX() + Math.max(1, size.getWidth() / 2);
		int y = loc.getY() + Math.max(1, size.getHeight() / 2);
		PointerInput finger = new PointerInput(PointerInput.Kind.TOUCH, "finger");
		Sequence press = new Sequence(finger, 0);
		press.addAction(finger.createPointerMove(Duration.ZERO, PointerInput.Origin.viewport(), x, y));
		press.addAction(finger.createPointerDown(PointerInput.MouseButton.LEFT.asArg()));
		press.addAction(finger.createPointerMove(Duration.ofMillis(Math.max(200, durationMs)), PointerInput.Origin.viewport(), x, y));
		press.addAction(finger.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));
		iosdriver.perform(Arrays.asList(press));
	}

	private boolean iosTapPasteMenuItem(IOSDriver iosdriver) {
		String[] xpaths = new String[] {
			"//XCUIElementTypeMenuItem[@name='Paste' or @label='Paste']",
			"//XCUIElementTypeButton[@name='Paste' or @label='Paste']",
			"//*[@name='Paste' or @label='Paste']"
		};
		for (String xpath : xpaths) {
			try {
				java.util.List<WebElement> found = iosdriver.findElements(By.xpath(xpath));
				if (found == null) {
					continue;
				}
				for (WebElement el : found) {
					try {
						if (el != null && el.isDisplayed()) {
							el.click();
							Reporter.log("Tapped the Paste menu item (" + xpath + ")");
							return true;
						}
					} catch (Exception ignored) {}
				}
			} catch (Exception ignored) {}
		}
		return false;
	}

	private void iosDismissPastePermissionIfPresent(IOSDriver iosdriver) {
		String[] xpaths = new String[] {
			"//XCUIElementTypeButton[contains(@name, 'Allow Paste') or contains(@label, 'Allow Paste')]",
			"//XCUIElementTypeButton[@name='Allow Paste' or @label='Allow Paste']",
			"//*[@name='Allow Paste' or @label='Allow Paste']"
		};
		for (String xpath : xpaths) {
			try {
				java.util.List<WebElement> found = iosdriver.findElements(By.xpath(xpath));
				if (found == null) {
					continue;
				}
				for (WebElement el : found) {
					try {
						if (el != null && el.isDisplayed()) {
							el.click();
							Reporter.log("Dismissed the iOS paste-permission alert (Allow Paste)");
							try { Thread.sleep(200); } catch (Exception ignored) {}
							return;
						}
					} catch (Exception ignored) {}
				}
			} catch (Exception ignored) {}
		}
	}

	private void iosLogLoginFieldValueLength(WebElement field, String strFieldName, int expectedLength) {
		try {
			String raw = null;
			try { raw = field.getAttribute("value"); } catch (Exception ignored) {}
			if (raw == null) {
				try { raw = field.getText(); } catch (Exception ignored) {}
			}
			if (raw == null) {
				Reporter.log("Login field (" + strFieldName + ") value was not readable after entry (expected length " + expectedLength + ")");
			} else {
				Reporter.log("Login field (" + strFieldName + ") value length=" + raw.length() + " (expected " + expectedLength + ")");
			}
		} catch (Exception e) {
			Reporter.log("Login field (" + strFieldName + ") value length could not be read: " + e.getMessage());
		}
	}

	private boolean iosLoginFieldLooksEmpty(WebElement field, int expectedLength) {
		if (expectedLength <= 0) {
			return false;
		}
		try {
			String raw = null;
			try { raw = field.getAttribute("value"); } catch (Exception ignored) {}
			if (raw == null) {
				try { raw = field.getText(); } catch (Exception ignored) {}
			}
			if (raw == null) {
				// Unreadable is not treated as empty; the paste click may still have worked.
				return false;
			}
			return raw.length() < Math.min(expectedLength, 10);
		} catch (Exception e) {
			return false;
		}
	}

	public void SENTRYMOBILE_AssertApiErrorOrUsableDegrade(Map<String, String> objDictionary, IOSDriver iosdriver, String strContext) {
		String source = SENTRYMOBILE_CaptureVisibleUi(iosdriver).toLowerCase();
		if (source.contains("error") || source.contains("try again") || source.contains("offline") || source.contains("timeout")) {
			Reporter.log("API error or degrade messaging shown after " + strContext);
			return;
		}
		if (SENTRYMOBILE_PageLooksLoggedIn(iosdriver)) {
			Reporter.log("App remained usable after " + strContext);
			return;
		}
		// TODO: tighten assertions once iOS proxy/DNS tooling exists
		Reporter.log("TODO: verify API failure handling after " + strContext);
	}

	public boolean SENTRYMOBILE_ClickRetryIfPresent(IOSDriver iosdriver) {
		return SENTRYMOBILE_ClickIfPresent(iosdriver, "//*[contains(@name, 'Retry') or contains(@name, 'Try Again')]", 3);
	}

	public boolean SENTRYMOBILE_DismissBiometricPromptIfPresent(IOSDriver iosdriver) {
		boolean dismissed = SENTRYMOBILE_ClickIfPresent(iosdriver, "//*[contains(@name, 'Cancel')]", 2);
		dismissed = SENTRYMOBILE_ClickIfPresent(iosdriver, "//*[contains(@name, 'Use Password')]", 2) || dismissed;
		if (dismissed) {
			Reporter.log("Dismissed a biometric or identity prompt");
		}
		return dismissed;
	}

	public void SENTRYMOBILE_RestoreDeviceNetworkAndPower(Map<String, String> objDictionary) {
		objDictionary.put("strAirplaneMode", "Disabled");
		objDictionary.put("strWIFI", "Enabled");
		objDictionary.put("strLocationServices", "Enabled");
		IOSDriver live = iosPreferLiveSessionDriver();
		if (!iosIsSessionAlive(live)) {
			Reporter.log("SENTRYMOBILE_RestoreDeviceNetworkAndPower skipped: Appium session is not alive (driver already quit). Location Services, Airplane Mode, and Wi-Fi were not restored.");
			iosClearNetworkLastStates(objDictionary);
			iosClearLocationServicesLastState(objDictionary);
			return;
		}
		this.iosdriver = live;
		try {
			SENTRYMOBILE_SET_LOCATION_MODE(objDictionary);
		} catch (Throwable e) {
			Reporter.log("Restore location services failed: " + e.getMessage());
			iosClearLocationServicesLastState(objDictionary);
		}
		try {
			iosSetAirplaneAndWifiInOneControlCenterVisit(objDictionary, false, true, false);
		} catch (Throwable e) {
			Reporter.log("Restore airplane mode / Wi-Fi failed: " + e.getMessage());
			iosClearNetworkLastStates(objDictionary);
		}
	}

	public void setAirplaneMode(boolean enabled) {
		iosSetControlCenterToggle(null, iosResolveControlCenterDriver(), "Airplane Mode", "Airplane",
				enabled, new String[] {"airplane-button", "airplane-mode-button"}, true);
	}

	public void setAirplaneMode(IOSDriver iosdriver, boolean enabled) {
		if (iosdriver != null) {
			this.iosdriver = iosdriver;
		}
		iosSetControlCenterToggle(null, iosResolveControlCenterDriver(), "Airplane Mode", "Airplane",
				enabled, new String[] {"airplane-button", "airplane-mode-button"}, true);
	}

	public void setWifi(boolean enabled) {
		if (!enabled) {
			Reporter.log("Note: turning Wi-Fi off from iOS Control Center disconnects the current network; it does not fully disable Wi-Fi, which may auto-rejoin later.");
		}
		iosSetControlCenterToggle(null, iosResolveControlCenterDriver(), "Wi-Fi", "Wi-Fi",
				enabled, new String[] {"wifi-button", "wifi-button-off", "wifi-button-on"}, true);
	}

	public void setWifi(IOSDriver iosdriver, boolean enabled) {
		if (iosdriver != null) {
			this.iosdriver = iosdriver;
		}
		setWifi(enabled);
	}

	public void SENTRYMOBILE_SET_AIRPLANE_MODE(Map<String, String> objDictionary) {
		boolean enabled = "Enabled".equalsIgnoreCase(String.valueOf(objDictionary.get("strAirplaneMode")));
		IOSDriver live = iosPreferLiveSessionDriver();
		if (!iosIsSessionAlive(live)) {
			Reporter.log("SENTRYMOBILE_SET_AIRPLANE_MODE requested=" + (enabled ? "Enabled" : "Disabled")
					+ " skipped: Appium session is not alive (driver already quit)");
			iosClearNetworkLastStates(objDictionary);
			return;
		}
		this.iosdriver = live;
		Reporter.log("SENTRYMOBILE_SET_AIRPLANE_MODE requested=" + (enabled ? "Enabled" : "Disabled"));
		iosSetControlCenterToggle(objDictionary, live, "Airplane Mode", "Airplane",
				enabled, new String[] {"airplane-button", "airplane-mode-button"}, true);
	}

	public void SENTRYMOBILE_SET_WIFI(Map<String, String> objDictionary) {
		String raw = objDictionary == null ? null : objDictionary.get("strWIFI");
		if (raw == null || raw.isBlank()) {
			Reporter.log("SENTRYMOBILE_SET_WIFI skipped: strWIFI is empty/default and must not turn Wi-Fi back on");
			return;
		}
		boolean enabled = iosIsExplicitWifiEnabled(raw);
		if (!enabled && !iosIsExplicitWifiDisabled(raw)) {
			Reporter.log("SENTRYMOBILE_SET_WIFI skipped: unrecognized strWIFI='" + raw + "'");
			return;
		}
		IOSDriver live = iosPreferLiveSessionDriver();
		if (!iosIsSessionAlive(live)) {
			Reporter.log("SENTRYMOBILE_SET_WIFI requested=" + (enabled ? "Enabled" : "Disabled")
					+ " skipped: Appium session is not alive (driver already quit)");
			iosClearNetworkLastStates(objDictionary);
			return;
		}
		this.iosdriver = live;
		Reporter.log("SENTRYMOBILE_SET_WIFI requested=" + (enabled ? "Enabled" : "Disabled"));
		if (!enabled) {
			Reporter.log("Note: turning Wi-Fi off from iOS Control Center disconnects the current network; it does not fully disable Wi-Fi, which may auto-rejoin later.");
		}
		iosSetControlCenterToggle(objDictionary, live, "Wi-Fi", "Wi-Fi",
				enabled, new String[] {"wifi-button", "wifi-button-off", "wifi-button-on"}, true);
	}

	private boolean iosIsExplicitWifiEnabled(String raw) {
		if (raw == null || raw.isBlank()) {
			return false;
		}
		String v = raw.trim();
		return "Enabled".equalsIgnoreCase(v) || "True".equalsIgnoreCase(v) || "On".equalsIgnoreCase(v);
	}

	private boolean iosIsExplicitWifiDisabled(String raw) {
		if (raw == null || raw.isBlank()) {
			return false;
		}
		String v = raw.trim();
		return "Disabled".equalsIgnoreCase(v) || "False".equalsIgnoreCase(v) || "Off".equalsIgnoreCase(v);
	}

	private boolean iosShouldApplyWifiSettingAfterAirplane(Map<String, String> objDictionary) {
		String raw = objDictionary == null ? null : objDictionary.get("strWIFI");
		if (raw == null || raw.isBlank()) {
			Reporter.log("Skipping SET_WIFI after driver setup: strWIFI is empty/default and must not turn Wi-Fi back on");
			return false;
		}
		boolean airplaneEnabled = objDictionary != null
				&& "Enabled".equalsIgnoreCase(String.valueOf(objDictionary.get("strAirplaneMode")));
		if (airplaneEnabled && iosIsExplicitWifiEnabled(raw)) {
			// Android-parity tests (I3000F_OpenApp_AirplaneModeEnabled and similar) set both
			// strWIFI=Enabled and strAirplaneMode=Enabled. On iOS, re-enabling Wi-Fi during
			// airplane mode restores connectivity and hides the No Internet error.
			// Leave Wi-Fi off; a later mid-test SENTRYMOBILE_SET_WIFI(Enabled) is still honored.
			Reporter.log("Skipping SET_WIFI Enabled after airplane mode was enabled; leaving Wi-Fi off so the device stays offline. Call SENTRYMOBILE_SET_WIFI mid-test if Wi-Fi during airplane is required.");
			return false;
		}
		return iosIsExplicitWifiEnabled(raw) || iosIsExplicitWifiDisabled(raw);
	}

	private boolean iosIsAirplaneToggle(String displayName, String searchToken) {
		return "Airplane".equals(searchToken)
				|| (displayName != null && displayName.toLowerCase().contains("airplane"));
	}

	private boolean iosIsAirplaneEnabledRequest(Map<String, String> objDictionary) {
		if (objDictionary == null) {
			return false;
		}
		String raw = objDictionary.get("strAirplaneMode");
		return raw != null && "Enabled".equalsIgnoreCase(raw.trim());
	}

	// Last known Airplane Mode / Wi-Fi states are kept in objDictionary under
	// "strAirplaneModeLastState" and "strWIFILastState" ("Enabled"/"Disabled").
	// BeforeMethod carries them across objDictionary.clear() so they survive app reinstalls.
	private String iosDesiredSetupAirplaneState(Map<String, String> objDictionary) {
		return iosIsAirplaneEnabledRequest(objDictionary) ? "Enabled" : "Disabled";
	}

	private String iosDesiredSetupWifiState(Map<String, String> objDictionary) {
		// With airplane Enabled, Wi-Fi is Disabled unless mid-test code later requests it on.
		// strWIFI=Enabled at driver setup (Android-parity tests) is not treated as that request.
		if (iosIsAirplaneEnabledRequest(objDictionary)) {
			return "Disabled";
		}
		String rawWifi = objDictionary == null ? null : objDictionary.get("strWIFI");
		return iosIsExplicitWifiDisabled(rawWifi) ? "Disabled" : "Enabled";
	}

	private void iosRecordNetworkLastStates(Map<String, String> objDictionary, Boolean airplaneOn, Boolean wifiOn) {
		if (objDictionary == null) {
			return;
		}
		if (airplaneOn == null) {
			objDictionary.remove("strAirplaneModeLastState");
			Reporter.log("Cleared strAirplaneModeLastState (verified state unknown)");
		} else {
			String value = airplaneOn ? "Enabled" : "Disabled";
			objDictionary.put("strAirplaneModeLastState", value);
			Reporter.log("Cached strAirplaneModeLastState=" + value);
		}
		if (wifiOn == null) {
			objDictionary.remove("strWIFILastState");
			Reporter.log("Cleared strWIFILastState (verified state unknown)");
		} else {
			String value = wifiOn ? "Enabled" : "Disabled";
			objDictionary.put("strWIFILastState", value);
			Reporter.log("Cached strWIFILastState=" + value);
		}
	}

	private void iosClearNetworkLastStates(Map<String, String> objDictionary) {
		if (objDictionary == null) {
			return;
		}
		objDictionary.remove("strAirplaneModeLastState");
		objDictionary.remove("strWIFILastState");
		Reporter.log("Cleared strAirplaneModeLastState and strWIFILastState so the next test will re-check Control Center");
	}

	private void iosApplySetupNetworkState(Map<String, String> objDictionary) {
		String wantedAirplane = iosDesiredSetupAirplaneState(objDictionary);
		String wantedWifi = iosDesiredSetupWifiState(objDictionary);
		String lastAirplane = objDictionary == null ? null : objDictionary.get("strAirplaneModeLastState");
		String lastWifi = objDictionary == null ? null : objDictionary.get("strWIFILastState");
		Reporter.log("SetMobileDriver setup: last airplane='" + lastAirplane + "' wifi='" + lastWifi
				+ "', wanted airplane='" + wantedAirplane + "' wifi='" + wantedWifi + "'");
		if (wantedAirplane.equalsIgnoreCase(lastAirplane) && wantedWifi.equalsIgnoreCase(lastWifi)) {
			Reporter.log("Airplane Mode already " + wantedAirplane + " and Wi-Fi already " + wantedWifi
					+ " (last known state) - skipped Control Center");
			return;
		}
		// Last state unknown (null) or different from the wanted state: open Control Center and apply.
		if (iosIsAirplaneEnabledRequest(objDictionary)) {
			Reporter.log("SetMobileDriver setup: strAirplaneMode=Enabled; using the airplane-enabled path (Wi-Fi off)");
			iosSetAirplaneAndWifiInOneControlCenterVisit(objDictionary, true, false, false);
			return;
		}
		String rawAirplane = objDictionary == null ? null : objDictionary.get("strAirplaneMode");
		String rawWifi = objDictionary == null ? null : objDictionary.get("strWIFI");
		// Null, empty, or anything other than Enabled (including Disabled) => airplane OFF.
		// Null/empty/Enabled strWIFI => Wi-Fi ON; only an explicit Disabled keeps Wi-Fi off.
		boolean wifiEnabled = !iosIsExplicitWifiDisabled(rawWifi);
		Reporter.log("SetMobileDriver setup: strAirplaneMode='" + rawAirplane
				+ "' is not Enabled; ensuring Airplane OFF and Wi-Fi " + (wifiEnabled ? "ON" : "OFF")
				+ " (strWIFI='" + rawWifi + "')");
		iosEnsureSetupAirplaneOffAndWifi(objDictionary, wifiEnabled);
	}

	private void iosEnsureSetupAirplaneOffAndWifi(Map<String, String> objDictionary, boolean wifiEnabled) {
		iosSetAirplaneAndWifiInOneControlCenterVisit(objDictionary, false, wifiEnabled, false);
	}

	private static volatile IOSDriver iosSharedSessionDriver;

	private static void iosRememberSharedSessionDriver(IOSDriver iosdriver) {
		iosSharedSessionDriver = iosdriver;
	}

	/**
	 * True when the driver still has a session id and will accept a cheap command.
	 * After quit() getSessionId() is null; do not issue further commands in that case.
	 */
	private static boolean iosIsSessionAlive(IOSDriver iosdriver) {
		if (iosdriver == null) {
			return false;
		}
		try {
			if (iosdriver.getSessionId() == null) {
				return false;
			}
			iosdriver.getSettings();
			return true;
		} catch (Exception e) {
			return false;
		}
	}

	/**
	 * Safety net for tests whose only quit() used to be inside UpdateErrorMessageWithPivotalData.
	 * Restores network/power first while the session is still alive, then quits if it still is.
	 * Safe to call after a test that already restored and quit: a dead session is skipped.
	 */
	public static void SENTRYMOBILE_AfterMethodRestoreAndQuitIfAlive(Map<String, String> objDictionary) {
		IOSDriver driver = iosSharedSessionDriver;
		if (driver == null) {
			return;
		}
		if (!iosIsSessionAlive(driver)) {
			if (iosSharedSessionDriver == driver) {
				iosSharedSessionDriver = null;
			}
			return;
		}
		try {
			IOS_Common_Flutter helper = new IOS_Common_Flutter();
			helper.iosdriver = driver;
			try {
				helper.SENTRYMOBILE_RestoreDeviceNetworkAndPower(objDictionary);
			} catch (Exception e) {
				Reporter.log("AfterMethod restore network/power before quit failed: " + e.getMessage());
			}
			if (iosIsSessionAlive(driver)) {
				driver.quit();
				Reporter.log("AfterMethod quit the Appium session that was still alive");
			}
		} catch (Exception e) {
			Reporter.log("AfterMethod quit failed: " + e.getMessage());
		} finally {
			if (iosSharedSessionDriver == driver) {
				iosSharedSessionDriver = null;
			}
		}
	}



	/**
	 * The shared field this framework updates (SetMobileDriver / mid-test reassignment).
	 * Prefer this over a stale local that a test may have captured before a new session.
	 */
	private IOSDriver iosPreferLiveSessionDriver() {
		if (iosIsSessionAlive(this.iosdriver)) {
			return this.iosdriver;
		}
		return this.iosdriver;
	}

	private void iosClearLocationServicesLastState(Map<String, String> objDictionary) {
		if (objDictionary == null) {
			return;
		}
		if (objDictionary.remove("strLocationServicesLastState") != null) {
			Reporter.log("Cleared strLocationServicesLastState so the next test will re-check Settings");
		}
	}


	private static class IosControlCenterScope {
		Object previousActiveApp;
		Object previousDetectionPoint;
		Object previousWaitForIdleTimeout;
		Object previousAnimationCoolOffTimeout;
		Object previousReduceMotion;
		boolean scopedToSpringBoard;
		boolean tunedIdle;
		boolean tunedReduceMotion;
	}

	private Dimension iosControlCenterWindowSize(IOSDriver iosdriver) {
		if (iosCcCachedWindowWidth != null && iosCcCachedWindowHeight != null) {
			return new Dimension(iosCcCachedWindowWidth.intValue(), iosCcCachedWindowHeight.intValue());
		}
		Dimension size = iosdriver.manage().window().getSize();
		if (size != null) {
			iosCcCachedWindowWidth = size.width;
			iosCcCachedWindowHeight = size.height;
		}
		return size;
	}

	private void iosClearControlCenterWindowCache() {
		iosCcCachedWindowWidth = null;
		iosCcCachedWindowHeight = null;
	}

	private boolean iosPollFor(int maxMs, BooleanSupplier condition) {
		long deadline = System.currentTimeMillis() + Math.max(0, maxMs);
		try {
			if (condition.getAsBoolean()) {
				return true;
			}
		} catch (Exception ignored) {}
		while (System.currentTimeMillis() < deadline) {
			iosGpsSleep(IOS_CC_POLL_INTERVAL_MS);
			try {
				if (condition.getAsBoolean()) {
					return true;
				}
			} catch (Exception ignored) {}
		}
		return false;
	}

	private String iosCcElementLog(WebElement el) {
		if (IOS_CC_DEBUG_ELEMENT_LOGS) {
			return iosCcElementLog(el);
		}
		if (el == null) {
			return "null";
		}
		try {
			String name = iosSafeAttribute(el, "name");
			if (name != null && !name.isBlank()) {
				return name;
			}
		} catch (Exception ignored) {}
		return "present";
	}

	private void iosRestoreXcuiSetting(IOSDriver iosdriver, String name, Object previous, Object fallbackIfNull) {
		try {
			Object value = previous != null ? previous : fallbackIfNull;
			if (value == null) {
				return;
			}
			iosdriver.setSetting(name, value);
		} catch (Exception e) {
			Reporter.log("Failed to restore " + name + ": " + e.getMessage());
		}
	}

	private IosControlCenterScope iosBeginControlCenterScope(IOSDriver iosdriver, String logLabel) {
		IosControlCenterScope scope = new IosControlCenterScope();
		if (iosdriver == null) {
			return scope;
		}
		try { iosdriver.context("NATIVE_APP"); } catch (Exception ignored) {}
		try {
			Map<String, Object> settings = iosdriver.getSettings();
			if (settings != null) {
				scope.previousActiveApp = settings.get("defaultActiveApplication");
				scope.previousDetectionPoint = settings.get("activeAppDetectionPoint");
				scope.previousWaitForIdleTimeout = settings.get("waitForIdleTimeout");
				scope.previousAnimationCoolOffTimeout = settings.get("animationCoolOffTimeout");
				scope.previousReduceMotion = settings.get("reduceMotion");
			}
		} catch (Exception e) {
			Reporter.log("Could not read current XCUITest settings before " + logLabel + ": " + e.getMessage());
		}
		try {
			iosdriver.setSetting("defaultActiveApplication", "com.apple.springboard");
			try {
				iosdriver.setSetting("activeAppDetectionPoint", "0.9,0.15");
			} catch (Exception e) {
				Reporter.log("Could not set activeAppDetectionPoint: " + e.getMessage());
			}
			scope.scopedToSpringBoard = true;
			Reporter.log("Scoped " + logLabel + " lookups to SpringBoard (defaultActiveApplication=com.apple.springboard, activeAppDetectionPoint=0.9,0.15)");
		} catch (Exception e) {
			Reporter.log("Could not set defaultActiveApplication to SpringBoard for " + logLabel + ": " + e.getMessage());
		}
		try {
			iosdriver.setSetting("waitForIdleTimeout", Double.valueOf(IOS_CC_WAIT_FOR_IDLE_TIMEOUT_SEC));
			iosdriver.setSetting("animationCoolOffTimeout", Double.valueOf(IOS_CC_ANIMATION_COOL_OFF_TIMEOUT_SEC));
			scope.tunedIdle = true;
			Reporter.log("Set waitForIdleTimeout=" + IOS_CC_WAIT_FOR_IDLE_TIMEOUT_SEC
					+ "s animationCoolOffTimeout=" + IOS_CC_ANIMATION_COOL_OFF_TIMEOUT_SEC
					+ "s for " + logLabel);
		} catch (Exception e) {
			Reporter.log("Could not lower WDA idle/cool-off timeouts for " + logLabel + ": " + e.getMessage());
		}
		try {
			iosdriver.setSetting("reduceMotion", Boolean.TRUE);
			scope.tunedReduceMotion = true;
		} catch (Exception e) {
			Reporter.log("Could not set reduceMotion for " + logLabel + ": " + e.getMessage());
		}
		return scope;
	}

	private void iosEndControlCenterScope(IOSDriver iosdriver, IosControlCenterScope scope, boolean activateApp, String logLabel) {
		iosClearControlCenterWindowCache();
		if (iosdriver == null || scope == null) {
			return;
		}
		if (scope.tunedIdle) {
			iosRestoreXcuiSetting(iosdriver, "waitForIdleTimeout", scope.previousWaitForIdleTimeout, Double.valueOf(10));
			iosRestoreXcuiSetting(iosdriver, "animationCoolOffTimeout", scope.previousAnimationCoolOffTimeout, Double.valueOf(2));
			Reporter.log("Restored waitForIdleTimeout/animationCoolOffTimeout after " + logLabel);
		}
		if (scope.tunedReduceMotion) {
			iosRestoreXcuiSetting(iosdriver, "reduceMotion", scope.previousReduceMotion, Boolean.FALSE);
		}
		if (scope.scopedToSpringBoard) {
			try {
				String restore = (scope.previousActiveApp != null && !String.valueOf(scope.previousActiveApp).isBlank()
						&& !"com.apple.springboard".equals(String.valueOf(scope.previousActiveApp)))
						? String.valueOf(scope.previousActiveApp) : "auto";
				iosdriver.setSetting("defaultActiveApplication", restore);
				Reporter.log("Restored defaultActiveApplication to " + restore + " after " + logLabel);
			} catch (Exception e) {
				Reporter.log("Failed to restore defaultActiveApplication after " + logLabel + ": " + e.getMessage());
			}
			try {
				if (scope.previousDetectionPoint != null) {
					iosdriver.setSetting("activeAppDetectionPoint", scope.previousDetectionPoint);
				}
			} catch (Exception e) {
				Reporter.log("Failed to restore activeAppDetectionPoint after " + logLabel + ": " + e.getMessage());
			}
		}
		if (activateApp) {
			try {
				iosdriver.activateApp(iosSessionAppBundle);
				Reporter.log("Re-activated app under test after " + logLabel + ": " + iosSessionAppBundle);
			} catch (Exception e) {
				Reporter.log("activateApp(" + iosSessionAppBundle + ") after " + logLabel + " failed: " + e.getMessage());
			}
		}
	}

	private boolean iosNetworkLastStatesMatch(Map<String, String> objDictionary, boolean airplaneEnabled, boolean wifiEnabled) {
		if (objDictionary == null) {
			return false;
		}
		String lastAirplane = objDictionary.get("strAirplaneModeLastState");
		String lastWifi = objDictionary.get("strWIFILastState");
		String wantedAirplane = airplaneEnabled ? "Enabled" : "Disabled";
		String wantedWifi = wifiEnabled ? "Enabled" : "Disabled";
		return wantedAirplane.equalsIgnoreCase(lastAirplane) && wantedWifi.equalsIgnoreCase(lastWifi);
	}

	/**
	 * Open Control Center once, set or verify Airplane Mode and Wi-Fi, then dismiss once.
	 * Enabling airplane still cycles OFF/ON when already ON and forces Wi-Fi off.
	 * Last-state cache is skipped when both requested end-states already match.
	 */
	private void iosSetAirplaneAndWifiInOneControlCenterVisit(Map<String, String> objDictionary,
			boolean airplaneEnabled, boolean wifiEnabled, boolean failIfUnavailable) {
		boolean effectiveWifiEnabled = airplaneEnabled ? false : wifiEnabled;
		if (iosNetworkLastStatesMatch(objDictionary, airplaneEnabled, effectiveWifiEnabled)) {
			Reporter.log("Airplane Mode already " + (airplaneEnabled ? "Enabled" : "Disabled")
					+ " and Wi-Fi already " + (effectiveWifiEnabled ? "Enabled" : "Disabled")
					+ " (last known state) - skipped Control Center");
			return;
		}
		IOSDriver iosdriver;
		try {
			iosdriver = iosResolveControlCenterDriver();
		} catch (Exception e) {
			iosControlCenterFail(objDictionary, null,
					"No IOSDriver is available to set Airplane Mode / Wi-Fi: " + e.getMessage(), failIfUnavailable, null);
			return;
		}
		if (!iosIsSessionAlive(iosdriver)) {
			iosControlCenterFail(objDictionary, iosdriver,
					"Appium session is not alive (driver already quit); cannot set Airplane Mode / Wi-Fi", failIfUnavailable, null);
			return;
		}
		this.iosdriver = iosdriver;
		if (airplaneEnabled && wifiEnabled) {
			Reporter.log("strWIFI='Enabled' is also set, but Wi-Fi will still be turned OFF while enabling airplane mode so the device stays offline. Call SENTRYMOBILE_SET_WIFI mid-test if Wi-Fi during airplane is required.");
		}

		if (IOS_NETWORK_TOGGLE_USE_SETTINGS) {
			Reporter.log("IOS_NETWORK_TOGGLE_USE_SETTINGS=true; skipping Control Center and using the Settings app path for airplane and Wi-Fi");
			Object previousActiveApp = null;
			try {
				Map<String, Object> settings = iosdriver.getSettings();
				if (settings != null) {
					previousActiveApp = settings.get("defaultActiveApplication");
				}
			} catch (Exception ignored) {}
			boolean airplaneSet = iosSetNetworkToggleViaSettings(objDictionary, iosdriver, "Airplane Mode", "Airplane", airplaneEnabled, previousActiveApp);
			boolean wifiSet;
			if (airplaneEnabled) {
				iosEnsureWifiOffAfterAirplaneEnabled(objDictionary, iosdriver, previousActiveApp, true);
				wifiSet = true;
			} else {
				wifiSet = iosSetNetworkToggleViaSettings(objDictionary, iosdriver, "Wi-Fi", "Wi-Fi", effectiveWifiEnabled, previousActiveApp);
				iosRecordNetworkLastStates(objDictionary, airplaneSet ? Boolean.valueOf(airplaneEnabled) : null,
						wifiSet ? Boolean.valueOf(effectiveWifiEnabled) : null);
			}
			if ((!airplaneSet || (!airplaneEnabled && !wifiSet)) && failIfUnavailable) {
				iosControlCenterFail(objDictionary, iosdriver,
						"Settings app path failed to set Airplane Mode / Wi-Fi", failIfUnavailable, null);
			}
			return;
		}

		String[] airplaneIds = new String[] {"airplane-button", "airplane-mode-button"};
		String[] wifiIds = new String[] {"wifi-button", "wifi-button-off", "wifi-button-on"};
		IosControlCenterScope scope = null;
		boolean skipControlCenterDismiss = false;
		try {
			scope = iosBeginControlCenterScope(iosdriver, "combined airplane/Wi-Fi");
			WebElement airplane = null;
			boolean controlCenterOpen = false;
			for (int attempt = 1; attempt <= 3 && !iosIsToggleOnScreen(airplane, iosdriver); attempt++) {
				if (iosIsControlCenterOpen(iosdriver)) {
					controlCenterOpen = true;
					Reporter.log("Control Center is already open; skipping the top-right open gesture on combined attempt " + attempt);
					iosDismissAirPlayPickerIfPresent(iosdriver);
				} else if (iosOpenControlCenter(iosdriver, attempt)) {
					controlCenterOpen = true;
					Reporter.log("Control Center is open on combined attempt " + attempt);
				} else {
					Reporter.log("Control Center did not appear open on combined attempt " + attempt);
					continue;
				}
				iosEnsureControlCenterPageOne(iosdriver, "Airplane Mode", "Airplane", airplaneIds);
				airplane = iosFindControlCenterToggle(iosdriver, "Airplane Mode", "Airplane", airplaneIds);
				if (!iosIsToggleOnScreen(airplane, iosdriver)) {
					Reporter.log("Airplane Mode toggle is still missing or off-screen after combined paging");
					if (!iosControlCenterIsOnConnectivityPage(iosdriver)) {
						iosDismissControlCenter(iosdriver, false);
						controlCenterOpen = false;
						airplane = null;
					}
				}
			}

			if (iosIsToggleOnScreen(airplane, iosdriver)) {
				boolean airplaneOk;
				if (airplaneEnabled) {
					airplaneOk = iosApplyAirplaneEnableSemantics(objDictionary, iosdriver, airplaneIds, failIfUnavailable);
					if (airplaneOk) {
						iosPollFor(IOS_CC_POLL_AIRPLANE_SETTLE_MAX_MS, () -> {
							WebElement wifi = iosFindControlCenterToggle(iosdriver, "Wi-Fi", "Wi-Fi", wifiIds);
							return iosReadControlCenterToggleState(iosdriver, wifi, "Wi-Fi", "Wi-Fi", wifiIds) != null;
						});
						iosEnsureWifiOffAfterAirplaneEnabled(objDictionary, iosdriver, scope != null ? scope.previousActiveApp : null, false);
					}
				} else {
					airplaneOk = iosTapControlCenterToggleToState(iosdriver, "Airplane Mode", "Airplane", airplaneIds, false);
					if (airplaneOk) {
						if (!iosTapControlCenterToggleToState(iosdriver, "Wi-Fi", "Wi-Fi", wifiIds, effectiveWifiEnabled)) {
							Reporter.log("Combined visit could not set Wi-Fi to " + (effectiveWifiEnabled ? "ON" : "OFF") + " from Control Center; trying Settings");
							try { iosDismissControlCenter(iosdriver, false); } catch (Exception ignored) {}
							skipControlCenterDismiss = true;
							boolean wifiSet = iosSetNetworkToggleViaSettings(objDictionary, iosdriver, "Wi-Fi", "Wi-Fi", effectiveWifiEnabled,
									scope != null ? scope.previousActiveApp : null);
							iosRecordNetworkLastStates(objDictionary, Boolean.FALSE, wifiSet ? Boolean.valueOf(effectiveWifiEnabled) : null);
						} else {
							iosLogFinalAirplaneAndWifiStates(objDictionary, iosdriver);
						}
					} else {
						Reporter.log("Combined visit could not turn Airplane Mode OFF from Control Center; falling back to Settings");
						try { iosDismissControlCenter(iosdriver, false); } catch (Exception ignored) {}
						skipControlCenterDismiss = true;
						boolean airplaneOff = iosSetNetworkToggleViaSettings(objDictionary, iosdriver, "Airplane Mode", "Airplane", false,
								scope != null ? scope.previousActiveApp : null);
						boolean wifiSet = iosSetNetworkToggleViaSettings(objDictionary, iosdriver, "Wi-Fi", "Wi-Fi", effectiveWifiEnabled,
								scope != null ? scope.previousActiveApp : null);
						iosRecordNetworkLastStates(objDictionary, airplaneOff ? Boolean.FALSE : null, wifiSet ? Boolean.valueOf(effectiveWifiEnabled) : null);
					}
				}
			} else {
				if (controlCenterOpen) {
					try { iosDismissControlCenter(iosdriver, false); } catch (Exception ignored) {}
					controlCenterOpen = false;
				}
				Reporter.log("Combined Control Center path did not find Airplane Mode; falling back to the Settings app");
				skipControlCenterDismiss = true;
				Object previousActiveApp = scope != null ? scope.previousActiveApp : null;
				boolean airplaneSet = iosSetNetworkToggleViaSettings(objDictionary, iosdriver, "Airplane Mode", "Airplane", airplaneEnabled, previousActiveApp);
				if (airplaneEnabled) {
					iosEnsureWifiOffAfterAirplaneEnabled(objDictionary, iosdriver, previousActiveApp, true);
				} else {
					boolean wifiSet = iosSetNetworkToggleViaSettings(objDictionary, iosdriver, "Wi-Fi", "Wi-Fi", effectiveWifiEnabled, previousActiveApp);
					iosRecordNetworkLastStates(objDictionary, airplaneSet ? Boolean.FALSE : null, wifiSet ? Boolean.valueOf(effectiveWifiEnabled) : null);
				}
				if (!airplaneSet) {
					iosControlCenterFail(objDictionary, iosdriver,
							"Could not set Airplane Mode / Wi-Fi from Control Center or the Settings app fallback",
							failIfUnavailable, iosDumpControlCenterPageSource(iosdriver));
				}
			}
		} catch (RuntimeException e) {
			throw e;
		} catch (Exception e) {
			iosControlCenterFail(objDictionary, iosdriver, "Combined airplane/Wi-Fi Control Center visit failed: " + e.getMessage(), failIfUnavailable, null);
		} finally {
			if (!skipControlCenterDismiss) {
				try {
					iosDismissControlCenter(iosdriver, false);
				} catch (Exception e) {
					Reporter.log("Control Center dismiss after combined airplane/Wi-Fi failed: " + e.getMessage());
				}
			}
			iosEndControlCenterScope(iosdriver, scope, true, "combined airplane/Wi-Fi");
		}
	}

	/** Enabling airplane: if already ON, cycle OFF then ON so iOS drops a remembered in-airplane Wi-Fi session. */
	private boolean iosApplyAirplaneEnableSemantics(Map<String, String> objDictionary, IOSDriver iosdriver,
			String[] airplaneIds, boolean failIfUnavailable) {
		WebElement toggle = iosFindControlCenterToggle(iosdriver, "Airplane Mode", "Airplane", airplaneIds);
		Boolean currentlyOn = iosReadControlCenterToggleState(iosdriver, toggle, "Airplane Mode", "Airplane", airplaneIds);
		Reporter.log("Airplane Mode Control Center toggle current=" + (currentlyOn == null ? "UNKNOWN" : (currentlyOn ? "ON" : "OFF"))
				+ " requested=ON element=[" + iosCcElementLog(toggle) + "]");
		if (currentlyOn == null) {
			Reporter.log("Airplane Mode toggle state could not be determined (no On/Off, 1/0, round-child, Selected, SSID, or hidden compact value); not tapping");
			return false;
		}
		if (currentlyOn.booleanValue()) {
			Reporter.log("Airplane Mode is already ON; cycling it OFF then ON so iOS clears remembered Wi-Fi");
			if (!iosTapControlCenterToggleToState(iosdriver, "Airplane Mode", "Airplane", airplaneIds, false)) {
				String sourcePath = iosDumpControlCenterPageSource(iosdriver);
				try { iosDismissControlCenter(iosdriver, false); } catch (Exception ignored) {}
				iosControlCenterFail(objDictionary, iosdriver,
						"Airplane Mode did not turn OFF during the cycle (already-ON path). Page source saved to " + sourcePath,
						failIfUnavailable, sourcePath);
				return false;
			}
			if (!iosTapControlCenterToggleToState(iosdriver, "Airplane Mode", "Airplane", airplaneIds, true)) {
				String sourcePath = iosDumpControlCenterPageSource(iosdriver);
				try { iosDismissControlCenter(iosdriver, false); } catch (Exception ignored) {}
				iosControlCenterFail(objDictionary, iosdriver,
						"Airplane Mode did not turn back ON after the cycle. Page source saved to " + sourcePath,
						failIfUnavailable, sourcePath);
				return false;
			}
			return true;
		}
		if (!iosTapControlCenterToggleToState(iosdriver, "Airplane Mode", "Airplane", airplaneIds, true)) {
			String sourcePath = iosDumpControlCenterPageSource(iosdriver);
			try { iosDismissControlCenter(iosdriver, false); } catch (Exception ignored) {}
			iosControlCenterFail(objDictionary, iosdriver,
					"Airplane Mode did not turn ON. Page source saved to " + sourcePath,
					failIfUnavailable, sourcePath);
			return false;
		}
		return true;
	}


	private IOSDriver iosResolveControlCenterDriver() {
		if (this.iosdriver != null) {
			return this.iosdriver;
		}
		throw new IllegalStateException("No active IOSDriver session is available to toggle Airplane Mode / Wi-Fi from Control Center");
	}

	private void iosSetControlCenterToggle(Map<String, String> objDictionary, IOSDriver iosdriver, String displayName,
			String searchToken, boolean enabled, String[] accessibilityIds, boolean failIfUnavailable) {
		if (iosdriver == null) {
			iosControlCenterFail(objDictionary, null, "No IOSDriver is available to set " + displayName + " to " + (enabled ? "Enabled" : "Disabled"), failIfUnavailable, null);
			return;
		}
		if (!iosIsSessionAlive(iosdriver)) {
			iosControlCenterFail(objDictionary, iosdriver, "Appium session is not alive (driver already quit); cannot set " + displayName
					+ " to " + (enabled ? "Enabled" : "Disabled"), failIfUnavailable, null);
			iosClearNetworkLastStates(objDictionary);
			return;
		}
		IosControlCenterScope scope = null;
		boolean usedSettingsPath = false;
		boolean skipControlCenterDismiss = false;
		try {
			scope = iosBeginControlCenterScope(iosdriver, "Control Center " + displayName);

			if (IOS_NETWORK_TOGGLE_USE_SETTINGS) {
				Reporter.log("IOS_NETWORK_TOGGLE_USE_SETTINGS=true; skipping Control Center and using the Settings app path");
				skipControlCenterDismiss = true;
				usedSettingsPath = iosSetNetworkToggleViaSettings(objDictionary, iosdriver, displayName, searchToken, enabled,
						scope != null ? scope.previousActiveApp : null);
				if (usedSettingsPath && iosIsAirplaneToggle(displayName, searchToken) && enabled) {
					iosEnsureWifiOffAfterAirplaneEnabled(objDictionary, iosdriver, scope != null ? scope.previousActiveApp : null, true);
				}
				if (!usedSettingsPath) {
					iosControlCenterFail(objDictionary, iosdriver,
							"Settings app path failed to set " + displayName + " to " + (enabled ? "Enabled" : "Disabled"),
							failIfUnavailable, iosDumpControlCenterPageSource(iosdriver));
				}
				return;
			}

			WebElement toggle = null;
			boolean controlCenterOpen = false;
			for (int attempt = 1; attempt <= 3 && !iosIsToggleOnScreen(toggle, iosdriver); attempt++) {
				if (iosIsControlCenterOpen(iosdriver)) {
					controlCenterOpen = true;
					Reporter.log("Control Center is already open; skipping the top-right open gesture on attempt " + attempt);
					iosDismissAirPlayPickerIfPresent(iosdriver);
				} else if (iosOpenControlCenter(iosdriver, attempt)) {
					controlCenterOpen = true;
					Reporter.log("Control Center is open on attempt " + attempt);
				} else {
					Reporter.log("Control Center did not appear open on attempt " + attempt + " (no cc-root-folder-view / Page control / Add Controls)");
					continue;
				}
				// iOS 18+/27 Control Center is vertically paged. If the Connectivity module is
				// already expanded (Page N of N, Connectivity), stay there and do not page away.
				// Do not swipe from the center (that lands on Now Playing and is consumed).
				iosEnsureControlCenterPageOne(iosdriver, displayName, searchToken, accessibilityIds);
				toggle = iosFindControlCenterToggle(iosdriver, displayName, searchToken, accessibilityIds);
				if (!iosIsToggleOnScreen(toggle, iosdriver)) {
					Reporter.log("Control Center " + displayName + " toggle is still missing or off-screen after paging");
					if (!iosControlCenterIsOnConnectivityPage(iosdriver)) {
						iosDismissControlCenter(iosdriver, false);
						controlCenterOpen = false;
						toggle = null;
					}
				}
			}
			if (iosIsToggleOnScreen(toggle, iosdriver)) {
				Boolean currentlyOn = iosReadControlCenterToggleState(iosdriver, toggle, displayName, searchToken, accessibilityIds);
				Reporter.log(displayName + " Control Center toggle current=" + (currentlyOn == null ? "UNKNOWN" : (currentlyOn ? "ON" : "OFF"))
						+ " requested=" + (enabled ? "ON" : "OFF")
						+ " element=[" + iosCcElementLog(toggle) + "]");
				if (currentlyOn == null) {
					Reporter.log(displayName + " toggle state could not be determined (no On/Off, 1/0, round-child, Selected, SSID, or hidden compact value); not tapping");
				} else if (iosIsAirplaneToggle(displayName, searchToken) && enabled) {
					if (!iosApplyAirplaneEnableSemantics(objDictionary, iosdriver, accessibilityIds, failIfUnavailable)) {
						return;
					}
					iosPollFor(IOS_CC_POLL_AIRPLANE_SETTLE_MAX_MS, () -> {
						String[] wifiIds = new String[] {"wifi-button", "wifi-button-off", "wifi-button-on"};
						WebElement wifi = iosFindControlCenterToggle(iosdriver, "Wi-Fi", "Wi-Fi", wifiIds);
						return iosReadControlCenterToggleState(iosdriver, wifi, "Wi-Fi", "Wi-Fi", wifiIds) != null;
					});
					iosEnsureWifiOffAfterAirplaneEnabled(objDictionary, iosdriver, scope != null ? scope.previousActiveApp : null, false);
				} else if (currentlyOn.booleanValue() != enabled) {
					if (!iosTapControlCenterToggleToState(iosdriver, displayName, searchToken, accessibilityIds, enabled)) {
						String sourcePath = iosDumpControlCenterPageSource(iosdriver);
						try { iosDismissControlCenter(iosdriver, false); } catch (Exception ignored) {}
						iosControlCenterFail(objDictionary, iosdriver,
								displayName + " Control Center toggle did not change to " + (enabled ? "ON" : "OFF") + " after tap (retried once). Page source saved to " + sourcePath,
								failIfUnavailable, sourcePath);
						return;
					}
				} else {
					Reporter.log(displayName + " already in the requested state; no tap");
				}
				Reporter.log("Set " + displayName + " via Control Center");
				// Airplane-enable already recorded inside iosEnsureWifiOffAfterAirplaneEnabled.
				if (!(iosIsAirplaneToggle(displayName, searchToken) && enabled)) {
					iosLogFinalAirplaneAndWifiStates(objDictionary, iosdriver);
				}
			} else {
				if (controlCenterOpen) {
					try { iosDismissControlCenter(iosdriver, false); } catch (Exception ignored) {}
					controlCenterOpen = false;
				}
				Reporter.log("Control Center page-dot path did not reach a visible " + displayName + " toggle; falling back to the Settings app");
				skipControlCenterDismiss = true;
				usedSettingsPath = iosSetNetworkToggleViaSettings(objDictionary, iosdriver, displayName, searchToken, enabled,
						scope != null ? scope.previousActiveApp : null);
				if (usedSettingsPath && iosIsAirplaneToggle(displayName, searchToken) && enabled) {
					iosEnsureWifiOffAfterAirplaneEnabled(objDictionary, iosdriver, scope != null ? scope.previousActiveApp : null, true);
				}
				if (!usedSettingsPath) {
					String sourcePath = iosDumpControlCenterPageSource(iosdriver);
					iosControlCenterFail(objDictionary, iosdriver,
							"Could not set " + displayName + " from Control Center page dots or the Settings app fallback. Page source saved to " + sourcePath,
							failIfUnavailable, sourcePath);
					return;
				}
			}
		} finally {
			if (!skipControlCenterDismiss) {
				try {
					iosDismissControlCenter(iosdriver, false);
				} catch (Exception e) {
					Reporter.log("Control Center dismiss in finally failed: " + e.getMessage());
				}
			}
			iosEndControlCenterScope(iosdriver, scope, true, "Control Center " + displayName);
		}
	}

	private boolean iosTapControlCenterToggleToState(IOSDriver iosdriver, String displayName, String searchToken,
			String[] accessibilityIds, boolean enabled) {
		WebElement toggle = iosFindControlCenterToggle(iosdriver, displayName, searchToken, accessibilityIds);
		if (!iosIsToggleOnScreen(toggle, iosdriver)) {
			Reporter.log("Cannot tap " + displayName + " to " + (enabled ? "ON" : "OFF") + ": toggle is not on screen");
			return false;
		}
		Boolean currentlyOn = iosReadControlCenterToggleState(iosdriver, toggle, displayName, searchToken, accessibilityIds);
		Reporter.log(displayName + " before tap current=" + (currentlyOn == null ? "UNKNOWN" : (currentlyOn ? "ON" : "OFF"))
				+ " requested=" + (enabled ? "ON" : "OFF")
				+ " element=[" + iosCcElementLog(toggle) + "]");
		if (currentlyOn == null) {
			Reporter.log(displayName + " state could not be determined; not tapping");
			return false;
		}
		if (currentlyOn.booleanValue() == enabled) {
			Reporter.log(displayName + " already " + (enabled ? "ON" : "OFF") + "; no tap");
			return true;
		}
		for (int tapAttempt = 1; tapAttempt <= 2; tapAttempt++) {
			iosTapControlCenterToggle(iosdriver, toggle, displayName, searchToken);
			iosControlCenterNetworkChanged = true;
			final WebElement[] holder = new WebElement[] { toggle };
			boolean flipped = iosPollFor(IOS_CC_POLL_TOGGLE_MAX_MS, () -> {
				WebElement after = iosFindControlCenterToggle(iosdriver, displayName, searchToken, accessibilityIds);
				if (iosIsToggleOnScreen(after, iosdriver)) {
					holder[0] = after;
				}
				Boolean nowOn = iosReadControlCenterToggleState(iosdriver, holder[0], displayName, searchToken, accessibilityIds);
				return Boolean.valueOf(enabled).equals(nowOn);
			});
			toggle = holder[0];
			Boolean nowOn = iosReadControlCenterToggleState(iosdriver, toggle, displayName, searchToken, accessibilityIds);
			Reporter.log(displayName + " after tap " + tapAttempt + "="
					+ (nowOn == null ? "UNKNOWN" : (nowOn ? "ON" : "OFF"))
					+ " element=[" + iosCcElementLog(toggle) + "]");
			if (flipped || Boolean.valueOf(enabled).equals(nowOn)) {
				return true;
			}
			if (tapAttempt == 1) {
				Reporter.log(displayName + " did not change to " + (enabled ? "ON" : "OFF") + " after the first tap; retrying once");
			}
		}
		return false;
	}

	private void iosEnsureWifiOffAfterAirplaneEnabled(Map<String, String> objDictionary, IOSDriver iosdriver,
			Object previousActiveApp, boolean viaSettings) {
		String rawWifi = objDictionary == null ? null : objDictionary.get("strWIFI");
		if (iosIsExplicitWifiEnabled(rawWifi)) {
			Reporter.log("strWIFI='" + rawWifi + "' is also set, but Wi-Fi will still be turned OFF while enabling airplane mode so the device stays offline. Call SENTRYMOBILE_SET_WIFI mid-test if Wi-Fi during airplane is required.");
		}
		if (viaSettings) {
			boolean wifiOff = iosSetNetworkToggleViaSettings(objDictionary, iosdriver, "Wi-Fi", "Wi-Fi", false, previousActiveApp);
			Reporter.log(wifiOff
					? "Set Wi-Fi OFF via the Settings app after enabling Airplane Mode"
					: "Could not turn Wi-Fi OFF via Settings after enabling Airplane Mode");
			Reporter.log("Final network state after enabling Airplane Mode (Settings path): Airplane=ON, Wi-Fi=" + (wifiOff ? "OFF" : "UNKNOWN"));
			iosRecordNetworkLastStates(objDictionary, Boolean.TRUE, wifiOff ? Boolean.FALSE : null);
			return;
		}
		String[] wifiIds = new String[] {"wifi-button", "wifi-button-off", "wifi-button-on"};
		WebElement wifi = iosFindControlCenterToggle(iosdriver, "Wi-Fi", "Wi-Fi", wifiIds);
		Boolean wifiOn = iosReadControlCenterToggleState(iosdriver, wifi, "Wi-Fi", "Wi-Fi", wifiIds);
		Reporter.log("Wi-Fi after Airplane Mode is ON: " + (wifiOn == null ? "UNKNOWN" : (wifiOn ? "ON" : "OFF"))
				+ (iosIsToggleOnScreen(wifi, iosdriver) ? " element=[" + iosCcElementLog(wifi) + "]" : " (toggle not on screen)"));
		if (Boolean.TRUE.equals(wifiOn)) {
			Reporter.log("Wi-Fi is still ON after enabling Airplane Mode; tapping it OFF");
			boolean wifiOff = iosTapControlCenterToggleToState(iosdriver, "Wi-Fi", "Wi-Fi", wifiIds, false);
			if (!wifiOff) {
				Reporter.log("Wi-Fi did not turn OFF after enabling Airplane Mode");
			}
		} else if (Boolean.FALSE.equals(wifiOn)) {
			Reporter.log("Wi-Fi is already OFF after enabling Airplane Mode; no tap");
		}
		iosLogFinalAirplaneAndWifiStates(objDictionary, iosdriver);
	}

	private void iosLogFinalAirplaneAndWifiStates(IOSDriver iosdriver) {
		iosLogFinalAirplaneAndWifiStates(null, iosdriver);
	}

	private void iosLogFinalAirplaneAndWifiStates(Map<String, String> objDictionary, IOSDriver iosdriver) {
		String[] airplaneIds = new String[] {"airplane-button", "airplane-mode-button"};
		String[] wifiIds = new String[] {"wifi-button", "wifi-button-off", "wifi-button-on"};
		WebElement airplane = iosFindControlCenterToggle(iosdriver, "Airplane Mode", "Airplane", airplaneIds);
		WebElement wifi = iosFindControlCenterToggle(iosdriver, "Wi-Fi", "Wi-Fi", wifiIds);
		Boolean airplaneOn = iosReadControlCenterToggleState(iosdriver, airplane, "Airplane Mode", "Airplane", airplaneIds);
		Boolean wifiOn = iosReadControlCenterToggleState(iosdriver, wifi, "Wi-Fi", "Wi-Fi", wifiIds);
		Reporter.log("Final Control Center network state: Airplane="
				+ (airplaneOn == null ? "UNKNOWN" : (airplaneOn ? "ON" : "OFF"))
				+ ", Wi-Fi=" + (wifiOn == null ? "UNKNOWN" : (wifiOn ? "ON" : "OFF")));
		iosRecordNetworkLastStates(objDictionary, airplaneOn, wifiOn);
	}

	private WebElement iosFindControlCenterToggle(IOSDriver iosdriver, String displayName, String searchToken, String[] accessibilityIds) {
		List<By> locators = new ArrayList<>();
		List<String> exactNames = new ArrayList<>();
		if (accessibilityIds != null) {
			for (String id : accessibilityIds) {
				if (id != null && !id.isBlank()) {
					exactNames.add(id);
				}
			}
		}
		if ("Wi-Fi".equals(searchToken) && !exactNames.contains("wifi-button")) {
			exactNames.add(0, "wifi-button");
		}
		if ("Airplane".equals(searchToken) && !exactNames.contains("airplane-button")) {
			exactNames.add(0, "airplane-button");
		}
		// Type-agnostic exact name match first: the expanded Connectivity page uses
		// XCUIElementTypeButton, while the compact page-1 module uses XCUIElementTypeOther
		// (ToggleButton). Visible on-screen hits are preferred over off-screen duplicates.
		for (String id : exactNames) {
			String escaped = id.replace("'", "\\'");
			locators.add(AppiumBy.iOSNsPredicateString("name == '" + escaped + "'"));
			locators.add(AppiumBy.accessibilityId(id));
			locators.add(AppiumBy.iOSClassChain("**/XCUIElementTypeButton[`name == '" + escaped + "'`]"));
			locators.add(AppiumBy.iOSClassChain("**/XCUIElementTypeOther[`name == '" + escaped + "'`]"));
		}
		String exactIn = "name IN {'wifi-button','airplane-button','airplane-mode-button','wifi-button-on','wifi-button-off'}";
		locators.add(AppiumBy.iOSNsPredicateString(exactIn));
		locators.add(AppiumBy.iOSClassChain("**/XCUIElementTypeButton[`" + exactIn + "`]"));
		locators.add(AppiumBy.iOSClassChain("**/XCUIElementTypeOther[`" + exactIn + "`]"));
		locators.add(AppiumBy.iOSClassChain("**/XCUIElementTypeSwitch[`" + exactIn + "`]"));
		// Broader fallbacks come last and are filtered to exclude the status-bar Wi-Fi image.
		String tokenEsc = searchToken == null ? "" : searchToken.replace("'", "\\'");
		locators.add(AppiumBy.iOSNsPredicateString(
				"type == 'XCUIElementTypeOther' AND (label == '" + displayName + "' OR label CONTAINS[c] '" + tokenEsc + "')"));

		WebElement offscreen = null;
		for (By by : locators) {
			try {
				List<WebElement> found = iosdriver.findElements(by);
				if (found == null) {
					continue;
				}
				for (WebElement el : found) {
					try {
						if (el == null || !iosElementLooksLikeRequestedToggle(el, displayName, searchToken, accessibilityIds)) {
							continue;
						}
						if (iosIsToggleOnScreen(el, iosdriver)) {
							Reporter.log("Found visible Control Center " + displayName + " toggle with locator: " + by
									+ " element=[" + iosCcElementLog(el) + "]");
							return el;
						}
						if (offscreen == null) {
							offscreen = el;
							Reporter.log("Found off-screen Control Center " + displayName + " toggle with locator: " + by
									+ " element=[" + iosCcElementLog(el) + "] (ignored for tapping)");
						}
					} catch (Exception ignored) {}
				}
			} catch (Exception e) {
				Reporter.log("Control Center locator missed (" + by + "): " + e.getMessage());
			}
		}
		return offscreen;
	}

	private boolean iosElementLooksLikeRequestedToggle(WebElement el, String displayName, String searchToken, String[] accessibilityIds) {
		if (iosIsStatusBarOrImage(el)) {
			return false;
		}
		String name = iosSafeAttribute(el, "name");
		String label = iosSafeAttribute(el, "label");
		if (accessibilityIds != null) {
			for (String id : accessibilityIds) {
				if (id != null && id.equalsIgnoreCase(name)) {
					return true;
				}
			}
		}
		if ("wifi-button".equalsIgnoreCase(name) && ("Wi-Fi".equals(searchToken) || "Wi-Fi".equalsIgnoreCase(label))) {
			return true;
		}
		if (("airplane-button".equalsIgnoreCase(name) || "airplane-mode-button".equalsIgnoreCase(name))
				&& ("Airplane".equals(searchToken) || (label != null && label.toLowerCase().contains("airplane")))) {
			return true;
		}
		// Do not treat a loose "Wi-Fi" / "Airplane" label match as sufficient — that hits the status bar.
		return false;
	}

	private boolean iosIsStatusBarOrImage(WebElement el) {
		String type = iosElementType(el);
		if (type != null) {
			String t = type.toLowerCase();
			if (t.contains("image") || t.contains("statusbar") || t.contains("statictext")) {
				return true;
			}
		}
		String name = iosSafeAttribute(el, "name");
		if (name == null) {
			return false;
		}
		// Status-bar glyph is name='wifi' (not wifi-button); "3 of 3 Wi-Fi bars" is the status-bar group.
		if (name.equalsIgnoreCase("wifi") || name.equalsIgnoreCase("airplane") || name.toLowerCase().contains("wi-fi bars")) {
			return true;
		}
		return false;
	}

	private String iosElementType(WebElement el) {
		for (String attr : new String[] {"type", "elementType"}) {
			String raw = iosSafeAttribute(el, attr);
			if (raw != null && !raw.isBlank()) {
				return raw;
			}
		}
		try {
			String tag = el.getTagName();
			if (tag != null && !tag.isBlank()) {
				return tag;
			}
		} catch (Exception ignored) {}
		return "";
	}

	private String iosSafeAttribute(WebElement el, String attr) {
		try {
			return el.getAttribute(attr);
		} catch (Exception ignored) {
			return null;
		}
	}

	private boolean iosIsToggleOnScreen(WebElement el, IOSDriver iosdriver) {
		if (el == null || iosdriver == null) {
			return false;
		}
		try {
			String visible = iosSafeAttribute(el, "visible");
			if ("false".equalsIgnoreCase(visible)) {
				return false;
			}
			if (Boolean.FALSE.equals(el.isDisplayed())) {
				return false;
			}
		} catch (Exception ignored) {}
		try {
			int y = el.getLocation().getY();
			Dimension window = iosControlCenterWindowSize(iosdriver);
			int height = window != null ? window.height : iosdriver.manage().window().getSize().height;
			if (y < 0 || y > height) {
				return false;
			}
		} catch (Exception ignored) {}
		return true;
	}

	private Boolean iosReadControlCenterToggleState(WebElement toggle) {
		return iosReadControlCenterToggleState(null, toggle, null, null, null);
	}

	private Boolean iosReadControlCenterToggleState(IOSDriver iosdriver, WebElement toggle, String displayName, String searchToken, String[] accessibilityIds) {
		if (toggle == null) {
			return null;
		}
		String label = displayName == null ? "toggle" : displayName;
		String rawValue = iosSafeAttribute(toggle, "value");
		Boolean fromValue = iosParseStrictToggleValue(rawValue);
		if (fromValue != null) {
			Reporter.log("Read " + label + " state from value='" + rawValue + "' -> " + (fromValue ? "ON" : "OFF"));
			return fromValue;
		}

		// Expanded Wi-Fi (and similar) tiles use an SSID / "Not Connected" value, not On/Off.
		// Prefer the child *-button-round value (1 = on) or its Selected trait.
		Boolean fromChild = iosReadRoundChildToggleState(toggle);
		if (fromChild != null) {
			Reporter.log("Read " + label + " state from *-button-round child -> " + (fromChild ? "ON" : "OFF"));
			return fromChild;
		}

		Boolean fromSelected = iosReadSelectedAttribute(toggle);
		if (fromSelected != null) {
			Reporter.log("Read " + label + " state from selected/traits -> " + (fromSelected ? "ON" : "OFF"));
			return fromSelected;
		}

		// "Not Connected" still means the radio is on; an SSID or carrier string also means ON.
		Boolean fromLoose = iosParseLooseToggleValue(rawValue);
		if (fromLoose != null) {
			Reporter.log("Read " + label + " state from non-boolean value='" + rawValue + "' -> " + (fromLoose ? "ON" : "OFF"));
			return fromLoose;
		}

		// Hidden compact-page XCUIElementTypeOther copies still carry a strict On/Off value.
		if (iosdriver != null) {
			Boolean fromHidden = iosReadHiddenCompactToggleState(iosdriver, searchToken, accessibilityIds);
			if (fromHidden != null) {
				Reporter.log("Read " + label + " state from hidden compact copy -> " + (fromHidden ? "ON" : "OFF"));
				return fromHidden;
			}
		}
		return null;
	}

	private Boolean iosParseStrictToggleValue(String raw) {
		if (raw == null || raw.isBlank()) {
			return null;
		}
		String v = raw.trim().toLowerCase();
		if (v.equals("1") || v.equals("on") || v.equals("true") || v.equals("yes")) {
			return Boolean.TRUE;
		}
		if (v.equals("0") || v.equals("off") || v.equals("false") || v.equals("no")) {
			return Boolean.FALSE;
		}
		return null;
	}

	private Boolean iosParseLooseToggleValue(String raw) {
		if (raw == null || raw.isBlank()) {
			return null;
		}
		String v = raw.trim().toLowerCase();
		if (v.equals("0") || v.equals("off") || v.equals("false") || v.equals("no")) {
			return Boolean.FALSE;
		}
		// "Not Connected" and SSID / carrier / "Contacts Only" strings mean the radio is on.
		return Boolean.TRUE;
	}

	private Boolean iosReadSelectedAttribute(WebElement el) {
		if (el == null) {
			return null;
		}
		try {
			String selected = el.getAttribute("selected");
			if (selected != null && !selected.isBlank()) {
				String v = selected.trim().toLowerCase();
				if (v.equals("true") || v.equals("1") || v.equals("on")) {
					return Boolean.TRUE;
				}
				if (v.equals("false") || v.equals("0") || v.equals("off")) {
					return Boolean.FALSE;
				}
			}
		} catch (Exception ignored) {}
		try {
			String traits = iosSafeAttribute(el, "traits");
			if (traits != null && traits.toLowerCase().contains("selected")) {
				return Boolean.TRUE;
			}
		} catch (Exception ignored) {}
		// Do not call isSelected() when selected/traits are absent: it often returns false
		// for expanded tiles whose value is an SSID, which would mis-read the radio as off.
		return null;
	}

	private Boolean iosReadRoundChildToggleState(WebElement toggle) {
		WebElement round = iosFindControlCenterRoundChild(toggle);
		if (round == null) {
			return null;
		}
		Boolean fromValue = iosParseStrictToggleValue(iosSafeAttribute(round, "value"));
		if (fromValue != null) {
			return fromValue;
		}
		return iosReadSelectedAttribute(round);
	}

	private WebElement iosFindControlCenterRoundChild(WebElement toggle) {
		if (toggle == null) {
			return null;
		}
		String[] predicates = {
			"name ENDSWITH '-button-round' OR name CONTAINS '-button-round'",
			"type == 'XCUIElementTypeButton' AND (value == '0' OR value == '1')"
		};
		for (String predicate : predicates) {
			try {
				List<WebElement> found = toggle.findElements(AppiumBy.iOSNsPredicateString(predicate));
				if (found == null) {
					continue;
				}
				for (WebElement el : found) {
					if (el == null) {
						continue;
					}
					try {
						if (Boolean.FALSE.equals(el.isDisplayed())) {
							continue;
						}
					} catch (Exception ignored) {}
					return el;
				}
			} catch (Exception ignored) {}
		}
		return null;
	}

	private Boolean iosReadHiddenCompactToggleState(IOSDriver iosdriver, String searchToken, String[] accessibilityIds) {
		List<String> names = new ArrayList<>();
		if (accessibilityIds != null) {
			for (String id : accessibilityIds) {
				if (id != null && !id.isBlank()) {
					names.add(id);
				}
			}
		}
		if ("Wi-Fi".equals(searchToken) && !names.contains("wifi-button")) {
			names.add("wifi-button");
		}
		if ("Airplane".equals(searchToken) && !names.contains("airplane-button")) {
			names.add("airplane-button");
		}
		if (names.isEmpty() || iosdriver == null) {
			return null;
		}
		StringBuilder in = new StringBuilder();
		for (int i = 0; i < names.size(); i++) {
			if (i > 0) {
				in.append(",");
			}
			in.append("'").append(names.get(i).replace("'", "\\'")).append("'");
		}
		try {
			List<WebElement> found = iosdriver.findElements(AppiumBy.iOSNsPredicateString(
					"(type == 'XCUIElementTypeOther' OR type == 'XCUIElementTypeButton') AND name IN {" + in + "}"));
			if (found == null) {
				return null;
			}
			for (WebElement el : found) {
				if (el == null || iosIsToggleOnScreen(el, iosdriver)) {
					continue;
				}
				Boolean state = iosParseStrictToggleValue(iosSafeAttribute(el, "value"));
				if (state != null) {
					Reporter.log("Hidden compact copy used for state: element=[" + iosCcElementLog(el) + "]");
					return state;
				}
			}
		} catch (Exception e) {
			Reporter.log("Hidden compact toggle state lookup failed: " + e.getMessage());
		}
		return null;
	}

	private String iosDescribeControlCenterElement(WebElement el) {
		if (el == null) {
			return "null";
		}
		String loc = "?";
		String size = "?";
		try {
			org.openqa.selenium.Point p = el.getLocation();
			loc = p.getX() + "," + p.getY();
		} catch (Exception ignored) {}
		try {
			org.openqa.selenium.Dimension d = el.getSize();
			size = d.getWidth() + "x" + d.getHeight();
		} catch (Exception ignored) {}
		return "type=" + iosElementType(el)
				+ " name=" + iosSafeAttribute(el, "name")
				+ " label=" + iosSafeAttribute(el, "label")
				+ " value=" + iosSafeAttribute(el, "value")
				+ " visible=" + iosSafeAttribute(el, "visible")
				+ " traits=" + iosSafeAttribute(el, "traits")
				+ " xy=" + loc
				+ " size=" + size;
	}

	private boolean iosIsControlCenterToggleOn(WebElement toggle) {
		return Boolean.TRUE.equals(iosReadControlCenterToggleState(toggle));
	}

	private boolean iosIsControlCenterOpen(IOSDriver iosdriver) {
		String[] predicates = {
			"name == 'cc-root-folder-view'",
			"name == 'Page control' OR type == 'XCUIElementTypePageIndicator'",
			"name == 'Add Controls' AND type == 'XCUIElementTypeButton'"
		};
		for (String predicate : predicates) {
			try {
				List<WebElement> found = iosdriver.findElements(AppiumBy.iOSNsPredicateString(predicate));
				if (found != null) {
					for (WebElement el : found) {
						try {
							if (el != null && el.isDisplayed()) {
								Reporter.log("Control Center open check: matched " + predicate);
								return true;
							}
						} catch (Exception ignored) {}
					}
				}
			} catch (Exception ignored) {}
		}
		try {
			List<WebElement> found = iosdriver.findElements(AppiumBy.accessibilityId("cc-root-folder-view"));
			if (found != null) {
				for (WebElement el : found) {
					if (el != null && el.isDisplayed()) {
						Reporter.log("Control Center open check: found cc-root-folder-view");
						return true;
					}
				}
			}
		} catch (Exception ignored) {}
		return false;
	}

	private boolean iosEnsureControlCenterPageOne(IOSDriver iosdriver, String displayName, String searchToken, String[] accessibilityIds) {
		if (iosControlCenterIsOnConnectivityPage(iosdriver)) {
			Reporter.log("Control Center is already on the expanded Connectivity page; not paging away");
			return true;
		}
		if (iosControlCenterReachedPageOne(iosdriver, displayName, searchToken, accessibilityIds)) {
			Reporter.log("Control Center already on page 1 or the " + displayName + " toggle is visible");
			return true;
		}

		// A1: tap the top of the vertical Page control (page 1 is the top dot) up to 3 times.
		WebElement indicator = iosFindControlCenterPageControl(iosdriver);
		if (indicator != null) {
			try {
				org.openqa.selenium.Point loc = indicator.getLocation();
				org.openqa.selenium.Dimension size = indicator.getSize();
				int tapX = loc.getX() + (size.getWidth() / 2);
				int tapY = loc.getY() + 12;
				for (int attempt = 1; attempt <= 3; attempt++) {
					if (iosControlCenterReachedPageOne(iosdriver, displayName, searchToken, accessibilityIds)) {
						return true;
					}
					Reporter.log("Tapping top of Control Center Page control at (" + tapX + "," + tapY + ") attempt " + attempt);
					iosTapAt(iosdriver, tapX, tapY);
					if (iosPollFor(IOS_CC_POLL_OPEN_MAX_MS, () -> iosControlCenterReachedPageOne(iosdriver, displayName, searchToken, accessibilityIds))) {
						Reporter.log("Control Center reached page 1 after Page control tap " + attempt);
						return true;
					}
				}
			} catch (Exception e) {
				Reporter.log("Page control top-tap failed: " + e.getMessage());
			}
		} else {
			Reporter.log("Control Center Page control was not found for top-tap paging");
		}

		// A2: drag on an empty side margin so Now Playing does not consume the gesture.
		if (iosControlCenterReachedPageOne(iosdriver, displayName, searchToken, accessibilityIds)) {
			return true;
		}
		Dimension window = iosdriver.manage().window().getSize();
		int fromY = (int) (window.height * 0.25);
		int toY = (int) (window.height * 0.9);
		int[] marginXs = { Math.max(1, window.width - 10), 15 };
		for (int marginX : marginXs) {
			try {
				Reporter.log("Paging Control Center with side-margin drag at x=" + marginX + " from y=" + fromY + " to y=" + toY);
				Map<String, Object> args = new HashMap<>();
				args.put("duration", 0.3);
				args.put("fromX", marginX);
				args.put("fromY", fromY);
				args.put("toX", marginX);
				args.put("toY", toY);
				iosdriver.executeScript("mobile: dragFromToForDuration", args);
			} catch (Exception e) {
				Reporter.log("Side-margin drag at x=" + marginX + " failed: " + e.getMessage());
				try {
					iosW3cSwipe(iosdriver, marginX, fromY, marginX, toY, 300);
				} catch (Exception ignored) {}
			}
			if (iosPollFor(IOS_CC_POLL_OPEN_MAX_MS, () -> iosControlCenterReachedPageOne(iosdriver, displayName, searchToken, accessibilityIds))) {
				Reporter.log("Control Center reached page 1 after side-margin drag at x=" + marginX);
				return true;
			}
		}

		// A3: mobile: swipe down on the Page control itself.
		if (iosControlCenterReachedPageOne(iosdriver, displayName, searchToken, accessibilityIds)) {
			return true;
		}
		indicator = iosFindControlCenterPageControl(iosdriver);
		if (indicator instanceof RemoteWebElement) {
			try {
				Map<String, Object> swipe = new HashMap<>();
				swipe.put("direction", "down");
				swipe.put("elementId", ((RemoteWebElement) indicator).getId());
				iosdriver.executeScript("mobile: swipe", swipe);
				Reporter.log("Paged Control Center with mobile: swipe down on Page control");
			} catch (Exception e) {
				Reporter.log("mobile: swipe down on Page control failed: " + e.getMessage());
			}
		}
		boolean reached = iosPollFor(IOS_CC_POLL_OPEN_MAX_MS, () -> iosControlCenterReachedPageOne(iosdriver, displayName, searchToken, accessibilityIds));
		if (!reached) {
			Reporter.log("Control Center page-dot/margin paging did not reach page 1 (Page control='" + iosReadControlCenterPageValue(iosdriver) + "')");
		}
		return reached;
	}

	private boolean iosControlCenterReachedPageOne(IOSDriver iosdriver, String displayName, String searchToken, String[] accessibilityIds) {
		String value = iosReadControlCenterPageValue(iosdriver);
		if (value != null) {
			String lower = value.toLowerCase();
			if (lower.contains("connectivity") || value.trim().matches("(?i)Page\\s+1(\\b).*")) {
				return true;
			}
		}
		WebElement toggle = iosFindControlCenterToggle(iosdriver, displayName, searchToken, accessibilityIds);
		return iosIsToggleOnScreen(toggle, iosdriver);
	}

	private boolean iosControlCenterIsOnConnectivityPage(IOSDriver iosdriver) {
		String value = iosReadControlCenterPageValue(iosdriver);
		if (value == null || value.isBlank()) {
			return false;
		}
		return value.toLowerCase().contains("connectivity");
	}

	private WebElement iosFindControlCenterPageControl(IOSDriver iosdriver) {
		try {
			List<WebElement> found = iosdriver.findElements(AppiumBy.iOSNsPredicateString(
					"name == 'Page control' OR type == 'XCUIElementTypePageIndicator'"));
			if (found != null) {
				for (WebElement el : found) {
					if (el != null) {
						return el;
					}
				}
			}
		} catch (Exception e) {
			Reporter.log("Could not locate Control Center Page control: " + e.getMessage());
		}
		return null;
	}

	private String iosReadControlCenterPageValue(IOSDriver iosdriver) {
		WebElement el = iosFindControlCenterPageControl(iosdriver);
		if (el == null) {
			return null;
		}
		String value = iosSafeAttribute(el, "value");
		if (value != null && !value.isBlank()) {
			Reporter.log("Control Center Page control value='" + value + "'");
			return value;
		}
		return null;
	}

	private int iosReadControlCenterPageNumber(IOSDriver iosdriver) {
		String value = iosReadControlCenterPageValue(iosdriver);
		if (value == null) {
			return -1;
		}
		Matcher matcher = Pattern.compile("Page\\s+(\\d+)\\s+of\\s+(\\d+)", Pattern.CASE_INSENSITIVE).matcher(value);
		if (matcher.find()) {
			return Integer.parseInt(matcher.group(1));
		}
		return -1;
	}

	private void iosTapControlCenterToggle(IOSDriver iosdriver, WebElement toggle, String displayName, String searchToken) {
		WebElement target = toggle;
		if ("Wi-Fi".equals(searchToken) || (displayName != null && displayName.toLowerCase().contains("wi-fi"))) {
			WebElement round = iosFindControlCenterRoundChild(toggle);
			if (round != null) {
				target = round;
				Reporter.log("Using " + displayName + " round child button as the tap target: [" + iosCcElementLog(round) + "]");
			}
		}
		org.openqa.selenium.Point loc = target.getLocation();
		org.openqa.selenium.Dimension size = target.getSize();
		int x = loc.getX() + Math.max(1, size.getWidth() / 2);
		int y = loc.getY() + Math.max(1, size.getHeight() / 2);
		Reporter.log("W3C-tapping Control Center " + displayName + " at (" + x + "," + y + ") element=[" + iosCcElementLog(target) + "]");
		try {
			iosW3cTap(iosdriver, x, y);
		} catch (Exception e) {
			Reporter.log("W3C tap of " + displayName + " failed: " + e.getMessage() + "; trying mobile: tap");
			try {
				iosTapAt(iosdriver, x, y);
			} catch (Exception e2) {
				Reporter.log("Coordinate tap of " + displayName + " failed: " + e2.getMessage() + "; falling back to element click");
				toggle.click();
			}
		}
	}

	private void iosTapAt(IOSDriver iosdriver, int x, int y) {
		try {
			Map<String, Object> tap = new HashMap<>();
			tap.put("x", x);
			tap.put("y", y);
			iosdriver.executeScript("mobile: tap", tap);
			return;
		} catch (Exception e) {
			Reporter.log("mobile: tap at (" + x + "," + y + ") failed: " + e.getMessage() + "; trying W3C pointer tap");
		}
		iosW3cTap(iosdriver, x, y);
	}

	private void iosW3cTap(IOSDriver iosdriver, int x, int y) {
		PointerInput finger = new PointerInput(PointerInput.Kind.TOUCH, "finger");
		Sequence tap = new Sequence(finger, 0);
		tap.addAction(finger.createPointerMove(Duration.ZERO, PointerInput.Origin.viewport(), x, y));
		tap.addAction(finger.createPointerDown(PointerInput.MouseButton.LEFT.asArg()));
		tap.addAction(finger.createPointerMove(Duration.ofMillis(50), PointerInput.Origin.viewport(), x, y));
		tap.addAction(finger.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));
		iosdriver.perform(Arrays.asList(tap));
	}

	private boolean iosSetNetworkToggleViaSettings(Map<String, String> objDictionary, IOSDriver iosdriver, String displayName,
			String searchToken, boolean enabled, Object previousActiveApp) {
		boolean activatedPreferences = false;
		try {
			try { iosDismissControlCenter(iosdriver, false); } catch (Exception ignored) {}
			try {
				iosdriver.activateApp("com.apple.Preferences");
			} catch (Exception e) {
				Map<String, Object> args = new HashMap<>();
				args.put("bundleId", "com.apple.Preferences");
				iosdriver.executeScript("mobile: activateApp", args);
			}
			activatedPreferences = true;
			try {
				iosdriver.setSetting("defaultActiveApplication", "com.apple.Preferences");
				Reporter.log("Scoped lookups to Settings (defaultActiveApplication=com.apple.Preferences)");
			} catch (Exception e) {
				Reporter.log("Could not set defaultActiveApplication to Preferences: " + e.getMessage());
			}
			iosGpsSleep(800);

			iosScrollSettingsToTop(iosdriver);

			WebElement toggle = null;
			if ("Airplane".equals(searchToken) || "Airplane Mode".equalsIgnoreCase(displayName)) {
				toggle = iosFindSettingsSwitch(iosdriver, "Airplane Mode");
			} else {
				if (!iosOpenSettingsWifiPage(iosdriver)) {
					Reporter.log("Could not open the Settings Wi-Fi page");
					return false;
				}
				toggle = iosFindSettingsSwitch(iosdriver, "Wi-Fi");
			}
			if (toggle == null) {
				Reporter.log("Could not find the Settings " + displayName + " switch");
				return false;
			}

			Boolean currentlyOn = iosReadControlCenterToggleState(toggle);
			Reporter.log(displayName + " Settings switch current=" + (currentlyOn == null ? "UNKNOWN" : (currentlyOn ? "ON" : "OFF")) + " requested=" + (enabled ? "ON" : "OFF"));
			if (currentlyOn == null) {
				Reporter.log(displayName + " Settings switch state is unknown; not tapping");
				return false;
			}
			if (currentlyOn.booleanValue() != enabled) {
				toggle.click();
				iosControlCenterNetworkChanged = true;
				iosGpsSleep(800);
				WebElement after = iosFindSettingsSwitch(iosdriver, "Airplane".equals(searchToken) ? "Airplane Mode" : "Wi-Fi");
				if (after == null) {
					after = toggle;
				}
				Boolean nowOn = iosReadControlCenterToggleState(after);
				Reporter.log(displayName + " Settings switch after tap=" + (nowOn == null ? "UNKNOWN" : (nowOn ? "ON" : "OFF")));
				if (!Boolean.valueOf(enabled).equals(nowOn)) {
					return false;
				}
			} else {
				Reporter.log(displayName + " already in the requested state in Settings; no tap");
			}

			iosNavigateBackInSettings(iosdriver);
			Reporter.log("Set " + displayName + " via Settings app path");
			return true;
		} catch (Exception e) {
			Reporter.log("Settings app path failed: " + e.getMessage());
			return false;
		} finally {
			if (activatedPreferences) {
				try {
					iosdriver.terminateApp("com.apple.Preferences");
					Reporter.log("Terminated com.apple.Preferences");
				} catch (Exception e) {
					try {
						Map<String, Object> args = new HashMap<>();
						args.put("bundleId", "com.apple.Preferences");
						iosdriver.executeScript("mobile: terminateApp", args);
						Reporter.log("Terminated com.apple.Preferences via mobile: terminateApp");
					} catch (Exception e2) {
						Reporter.log("terminateApp(com.apple.Preferences) failed: " + e2.getMessage());
					}
				}
			}
			try {
				String restore = (previousActiveApp != null && !String.valueOf(previousActiveApp).isBlank()
						&& !"com.apple.springboard".equals(String.valueOf(previousActiveApp))
						&& !"com.apple.Preferences".equals(String.valueOf(previousActiveApp)))
						? String.valueOf(previousActiveApp) : "auto";
				iosdriver.setSetting("defaultActiveApplication", restore);
				Reporter.log("Restored defaultActiveApplication to " + restore + " after Settings");
			} catch (Exception e) {
				Reporter.log("Failed to restore defaultActiveApplication after Settings: " + e.getMessage());
			}
		}
	}

	private void iosScrollSettingsToTop(IOSDriver iosdriver) {
		for (int i = 0; i < 3; i++) {
			try {
				Map<String, Object> scroll = new HashMap<>();
				scroll.put("direction", "up");
				iosdriver.executeScript("mobile: scroll", scroll);
			} catch (Exception e) {
				Reporter.log("mobile: scroll up in Settings failed: " + e.getMessage());
			}
		}
		try {
			Dimension size = iosdriver.manage().window().getSize();
			iosTapAt(iosdriver, size.width / 2, 5);
			Reporter.log("Tapped the status bar to scroll Settings to the top");
		} catch (Exception e) {
			Reporter.log("Status-bar tap to scroll Settings to top failed: " + e.getMessage());
		}
		iosGpsSleep(400);
	}

	private boolean iosOpenSettingsWifiPage(IOSDriver iosdriver) {
		String[] predicates = {
			"type == 'XCUIElementTypeCell' AND (name == 'Wi-Fi' OR label == 'Wi-Fi')",
			"type == 'XCUIElementTypeStaticText' AND (name == 'Wi-Fi' OR label == 'Wi-Fi')"
		};
		for (String predicate : predicates) {
			WebElement cell = iosFindSettingsElement(iosdriver, predicate);
			if (cell != null) {
				try {
					cell.click();
					Reporter.log("Opened Settings Wi-Fi page via " + predicate);
					iosGpsSleep(800);
					return true;
				} catch (Exception e) {
					Reporter.log("Tapping Settings Wi-Fi row failed: " + e.getMessage());
				}
			}
		}
		return false;
	}

	private WebElement iosFindSettingsSwitch(IOSDriver iosdriver, String name) {
		String escaped = name.replace("'", "\\'");
		return iosFindSettingsElement(iosdriver,
				"type == 'XCUIElementTypeSwitch' AND (name == '" + escaped + "' OR label == '" + escaped + "')");
	}

	private WebElement iosFindSettingsElement(IOSDriver iosdriver, String predicate) {
		for (int attempt = 1; attempt <= 5; attempt++) {
			try {
				List<WebElement> found = iosdriver.findElements(AppiumBy.iOSNsPredicateString(predicate));
				if (found != null) {
					for (WebElement el : found) {
						try {
							if (el != null && el.isDisplayed()) {
								return el;
							}
						} catch (Exception ignored) {}
					}
				}
			} catch (Exception e) {
				Reporter.log("Settings locator missed (" + predicate + "): " + e.getMessage());
			}
			iosGpsSleep(400);
		}
		return null;
	}

	private void iosNavigateBackInSettings(IOSDriver iosdriver) {
		String[] predicates = {
			"type == 'XCUIElementTypeButton' AND (name == 'Settings' OR label == 'Settings')",
			"type == 'XCUIElementTypeButton' AND (name == 'Back' OR label == 'Back')"
		};
		for (String predicate : predicates) {
			WebElement back = iosFindSettingsElement(iosdriver, predicate);
			if (back != null) {
				try {
					back.click();
					Reporter.log("Navigated back in Settings via " + predicate);
					iosGpsSleep(400);
					return;
				} catch (Exception e) {
					Reporter.log("Settings back tap failed: " + e.getMessage());
				}
			}
		}
		try {
			iosdriver.navigate().back();
			iosGpsSleep(400);
		} catch (Exception e) {
			Reporter.log("Settings navigate().back() failed: " + e.getMessage());
		}
	}

	private boolean iosOpenControlCenter(IOSDriver iosdriver, int attempt) {
		Dimension size = iosControlCenterWindowSize(iosdriver);
		// Face ID iPhones: open Control Center from the top-right (top-left is Notification Center).
		// Use a short flick that ends in empty header space above the module grid (modules start
		// around y=128). Mid-X (~width/2) stays away from Add Controls (38,23), Power (323,23),
		// and Now Playing's AirPlay button (mru-router-upper, roughly x=298-339, y~145).
		int fromX = Math.max(1, size.width - 20);
		int fromY = 2;
		int toX = Math.max(1, size.width / 2);
		int toY = Math.max(fromY + 20, (int) Math.round(size.height * 0.12));
		double dragDuration = (attempt <= 1) ? 0.15 : 0.2;
		int w3cMs = 250;
		Reporter.log("Opening Control Center (attempt " + attempt + ") short flick from (" + fromX + "," + fromY
				+ ") to (" + toX + "," + toY + ") window=" + size.width + "x" + size.height
				+ " dragDuration=" + dragDuration + "s w3cMs=" + w3cMs);
		if (attempt <= 2) {
			iosPerformControlCenterOpenFlick(iosdriver, fromX, fromY, toX, toY, dragDuration, w3cMs, "attempt " + attempt);
		} else {
			Reporter.log("Using W3C short flick (" + w3cMs + "ms) from top-right to open Control Center");
			try {
				iosW3cSwipe(iosdriver, fromX, fromY, toX, toY, w3cMs);
			} catch (Exception e) {
				Reporter.log("W3C open flick failed on attempt " + attempt + ": " + e.getMessage());
			}
		}
		boolean opened = iosPollFor(IOS_CC_POLL_OPEN_MAX_MS, () -> iosIsControlCenterOpen(iosdriver));
		if (opened) {
			iosDismissAirPlayPickerIfPresent(iosdriver);
		}
		return opened;
	}

	private boolean iosPerformControlCenterOpenFlick(IOSDriver iosdriver, int fromX, int fromY, int toX, int toY,
			double dragDurationSec, int w3cDurationMs, String label) {
		try {
			Map<String, Object> args = new HashMap<>();
			args.put("duration", dragDurationSec);
			args.put("fromX", fromX);
			args.put("fromY", fromY);
			args.put("toX", toX);
			args.put("toY", toY);
			iosdriver.executeScript("mobile: dragFromToForDuration", args);
			Reporter.log("Used mobile: dragFromToForDuration (" + dragDurationSec + "s) to open Control Center (" + label + ")");
			return true;
		} catch (Exception e) {
			Reporter.log("mobile: dragFromToForDuration failed for " + label + " (" + e.getMessage() + ")");
			try {
				Reporter.log("Falling back to a W3C short flick (" + w3cDurationMs + "ms) for " + label);
				iosW3cSwipe(iosdriver, fromX, fromY, toX, toY, w3cDurationMs);
				return true;
			} catch (Exception e2) {
				Reporter.log("W3C short flick failed for " + label + ": " + e2.getMessage());
				return false;
			}
		}
	}

	private boolean iosIsAirPlayPickerVisible(IOSDriver iosdriver) {
		String[] predicates = {
			"name == 'Route Picker Items'",
			"name CONTAINS[c] 'Route Picker'",
			"type == 'XCUIElementTypeCollectionView' AND (name CONTAINS[c] 'AirPlay' OR label CONTAINS[c] 'AirPlay')"
		};
		for (String predicate : predicates) {
			try {
				List<WebElement> found = iosdriver.findElements(AppiumBy.iOSNsPredicateString(predicate));
				if (found == null) {
					continue;
				}
				for (WebElement el : found) {
					try {
						if (el != null && el.isDisplayed()) {
							String visible = iosSafeAttribute(el, "visible");
							if ("false".equalsIgnoreCase(visible)) {
								continue;
							}
							Reporter.log("AirPlay / route picker is visible; matched " + predicate
									+ " element=[" + iosCcElementLog(el) + "]");
							return true;
						}
					} catch (Exception ignored) {}
				}
			} catch (Exception ignored) {}
		}
		return false;
	}

	private void iosDismissAirPlayPickerIfPresent(IOSDriver iosdriver) {
		if (!iosIsAirPlayPickerVisible(iosdriver)) {
			return;
		}
		Reporter.log("Dismissing the AirPlay / route picker before looking up Control Center toggles");
		Dimension size = iosdriver.manage().window().getSize();
		int tapX = Math.max(1, size.width / 2);
		int tapY = Math.max(20, (int) Math.round(size.height * 0.12));
		try {
			Reporter.log("Tapping empty header space at (" + tapX + "," + tapY + ") to dismiss AirPlay");
			iosW3cTap(iosdriver, tapX, tapY);
		} catch (Exception e) {
			Reporter.log("AirPlay dismiss tap failed: " + e.getMessage() + "; trying mobile: tap");
			try {
				iosTapAt(iosdriver, tapX, tapY);
			} catch (Exception e2) {
				Reporter.log("AirPlay dismiss mobile: tap also failed: " + e2.getMessage());
			}
		}
		if (iosPollFor(IOS_CC_POLL_CLOSE_MAX_MS, () -> !iosIsAirPlayPickerVisible(iosdriver))) {
			Reporter.log("AirPlay / route picker dismissed after the header tap");
			return;
		}
		try {
			int fromX = tapX;
			int fromY = (int) (size.height * 0.85);
			int toY = (int) (size.height * 0.15);
			Reporter.log("AirPlay picker still visible; swiping up once from (" + fromX + "," + fromY + ") to (" + fromX + "," + toY + ")");
			iosW3cSwipe(iosdriver, fromX, fromY, fromX, toY, 250);
		} catch (Exception e) {
			Reporter.log("AirPlay dismiss swipe-up failed: " + e.getMessage());
		}
		iosPollFor(IOS_CC_POLL_CLOSE_MAX_MS, () -> !iosIsAirPlayPickerVisible(iosdriver));
		if (iosIsAirPlayPickerVisible(iosdriver)) {
			Reporter.log("AirPlay / route picker is still visible after dismiss attempts");
		} else {
			Reporter.log("AirPlay / route picker dismissed after the swipe-up");
		}
	}

	private void iosW3cSwipe(IOSDriver iosdriver, int fromX, int fromY, int toX, int toY, int durationMs) {
		PointerInput finger = new PointerInput(PointerInput.Kind.TOUCH, "finger");
		Sequence swipe = new Sequence(finger, 0);
		swipe.addAction(finger.createPointerMove(Duration.ZERO, PointerInput.Origin.viewport(), fromX, fromY));
		swipe.addAction(finger.createPointerDown(PointerInput.MouseButton.LEFT.asArg()));
		swipe.addAction(finger.createPointerMove(Duration.ofMillis(durationMs), PointerInput.Origin.viewport(), toX, toY));
		swipe.addAction(finger.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));
		iosdriver.perform(Arrays.asList(swipe));
	}

	private void iosExpandConnectivityModule(IOSDriver iosdriver) {
		String[] predicates = {
			"name CONTAINS[c] 'Connectivity' OR label CONTAINS[c] 'Connectivity'",
			"name CONTAINS[c] 'Wireless' OR label CONTAINS[c] 'Wireless'",
			"name CONTAINS[c] 'Cellular' OR label CONTAINS[c] 'Cellular'",
			"name IN {'wifi-button','airplane-mode-button'} OR label CONTAINS[c] 'Wi-Fi' OR label CONTAINS[c] 'Airplane'"
		};
		for (String predicate : predicates) {
			try {
				List<WebElement> els = iosdriver.findElements(AppiumBy.iOSNsPredicateString(predicate));
				if (els == null || els.isEmpty()) {
					continue;
				}
				WebElement el = els.get(0);
				org.openqa.selenium.Point loc = el.getLocation();
				Dimension sz = el.getSize();
				int x = loc.getX() + Math.max(1, sz.width / 2);
				int y = loc.getY() + Math.max(1, sz.height / 2);
				PointerInput finger = new PointerInput(PointerInput.Kind.TOUCH, "finger");
				Sequence press = new Sequence(finger, 0);
				press.addAction(finger.createPointerMove(Duration.ZERO, PointerInput.Origin.viewport(), x, y));
				press.addAction(finger.createPointerDown(PointerInput.MouseButton.LEFT.asArg()));
				press.addAction(finger.createPointerMove(Duration.ofMillis(1200), PointerInput.Origin.viewport(), x, y));
				press.addAction(finger.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));
				iosdriver.perform(Arrays.asList(press));
				iosGpsSleep(700);
				Reporter.log("Long-pressed Control Center module matching: " + predicate);
				return;
			} catch (Exception e) {
				Reporter.log("Connectivity module long-press missed (" + predicate + "): " + e.getMessage());
			}
		}
	}

	private void iosDismissControlCenter(IOSDriver iosdriver, boolean reactivateApp) {
		if (iosdriver == null) {
			return;
		}
		Object previousActiveApp = null;
		boolean scopedToSpringBoard = false;
		boolean pressedHome = false;
		try {
			try {
				Map<String, Object> settings = iosdriver.getSettings();
				if (settings != null) {
					previousActiveApp = settings.get("defaultActiveApplication");
				}
			} catch (Exception e) {
				Reporter.log("Could not read defaultActiveApplication before Control Center dismiss: " + e.getMessage());
			}
			if (!"com.apple.springboard".equals(String.valueOf(previousActiveApp))) {
				try {
					iosdriver.setSetting("defaultActiveApplication", "com.apple.springboard");
					scopedToSpringBoard = true;
					Reporter.log("Scoped Control Center dismiss checks to SpringBoard (defaultActiveApplication=com.apple.springboard)");
				} catch (Exception e) {
					Reporter.log("Could not set defaultActiveApplication to SpringBoard for dismiss: " + e.getMessage());
				}
			}

			if (!iosIsControlCenterOpen(iosdriver)) {
				Reporter.log("Control Center is already closed; no dismiss needed");
			} else if (iosPressHomeButton(iosdriver, "primary dismiss")) {
				pressedHome = true;
				if (iosPollFor(IOS_CC_POLL_CLOSE_MAX_MS, () -> !iosIsControlCenterOpen(iosdriver))) {
					Reporter.log("Closed Control Center with mobile: pressButton home");
				} else {
					Reporter.log("Control Center still open after Home; trying a short bottom-edge flick up");
					iosFlickUpFromBottomEdgeToDismissControlCenter(iosdriver);
					if (iosPollFor(IOS_CC_POLL_CLOSE_MAX_MS, () -> !iosIsControlCenterOpen(iosdriver))) {
						Reporter.log("Closed Control Center with a short bottom-edge flick up");
					} else {
						Reporter.log("Control Center still open after the bottom-edge flick; trying last-resort header tap / Home");
						String lastResort = iosLastResortDismissControlCenter(iosdriver);
						if (lastResort != null && lastResort.toLowerCase().contains("home")) {
							pressedHome = true;
						}
						if (!iosIsControlCenterOpen(iosdriver)) {
							Reporter.log("Closed Control Center with " + lastResort);
						} else {
							Reporter.log("Control Center is still open after Home, bottom-edge flick, header tap, and a second Home press");
						}
					}
				}
			} else {
				Reporter.log("Home button press failed; trying a short bottom-edge flick up");
				iosFlickUpFromBottomEdgeToDismissControlCenter(iosdriver);
				if (iosPollFor(IOS_CC_POLL_CLOSE_MAX_MS, () -> !iosIsControlCenterOpen(iosdriver))) {
					Reporter.log("Closed Control Center with a short bottom-edge flick up");
				} else {
					Reporter.log("Control Center still open after the bottom-edge flick; trying last-resort header tap / Home");
					String lastResort = iosLastResortDismissControlCenter(iosdriver);
					if (lastResort != null && lastResort.toLowerCase().contains("home")) {
						pressedHome = true;
					}
					if (!iosIsControlCenterOpen(iosdriver)) {
						Reporter.log("Closed Control Center with " + lastResort);
					} else {
						Reporter.log("Control Center is still open after Home, bottom-edge flick, header tap, and a second Home press");
					}
				}
			}
		} catch (Exception e) {
			Reporter.log("Control Center dismiss failed: " + e.getMessage());
		} finally {
			boolean springBoardFrontmost = iosIsSpringBoardFrontmost(iosdriver);
			boolean shouldActivate = reactivateApp || pressedHome || springBoardFrontmost;
			if (shouldActivate) {
				String reason;
				if (reactivateApp) {
					reason = "reactivateApp=true";
				} else if (pressedHome) {
					reason = "Home press sent the app to the background";
				} else {
					reason = "SpringBoard was frontmost after dismiss";
				}
				try {
					iosdriver.activateApp(iosSessionAppBundle);
					Reporter.log("Re-activated app under test after Control Center dismiss (" + reason + "): " + iosSessionAppBundle);
				} catch (Exception e) {
					Reporter.log("activateApp(" + iosSessionAppBundle + ") after Control Center failed (" + reason + "): " + e.getMessage());
				}
			}
			if (reactivateApp) {
				try {
					iosdriver.setSetting("defaultActiveApplication", "auto");
					Reporter.log("Restored defaultActiveApplication to auto after Control Center dismiss");
				} catch (Exception e) {
					Reporter.log("Failed to restore defaultActiveApplication to auto after dismiss: " + e.getMessage());
				}
			} else if (scopedToSpringBoard) {
				try {
					String restore = (previousActiveApp != null && !String.valueOf(previousActiveApp).isBlank())
							? String.valueOf(previousActiveApp) : "auto";
					if (!"com.apple.springboard".equals(restore)) {
						iosdriver.setSetting("defaultActiveApplication", restore);
						Reporter.log("Restored defaultActiveApplication to " + restore + " after dismiss checks");
					}
				} catch (Exception e) {
					Reporter.log("Failed to restore defaultActiveApplication after dismiss checks: " + e.getMessage());
				}
			}
		}
	}

	private boolean iosIsSpringBoardFrontmost(IOSDriver iosdriver) {
		if (iosdriver == null) {
			return false;
		}
		try {
			Object info = iosdriver.executeScript("mobile: activeAppInfo");
			if (info instanceof Map) {
				Object bundle = ((Map<?, ?>) info).get("bundleId");
				if (bundle != null) {
					String bundleId = String.valueOf(bundle);
					if ("com.apple.springboard".equals(bundleId)) {
						Reporter.log("SpringBoard is frontmost after Control Center dismiss (mobile: activeAppInfo bundleId=" + bundleId + ")");
						return true;
					}
					if (iosSessionAppBundle != null && iosSessionAppBundle.equals(bundleId)) {
						return false;
					}
				}
			}
		} catch (Exception e) {
			Reporter.log("mobile: activeAppInfo failed: " + e.getMessage());
		}
		if (iosSessionAppBundle != null && !iosSessionAppBundle.isBlank()) {
			try {
				Map<String, Object> args = new HashMap<>();
				args.put("bundleId", iosSessionAppBundle);
				Object state = iosdriver.executeScript("mobile: queryAppState", args);
				if (state != null) {
					int appState = Integer.parseInt(String.valueOf(state).trim());
					// 4 = RUNNING_IN_FOREGROUND. Any other state means the app is not in front.
					if (appState != 4) {
						Reporter.log("App under test is not foreground after Control Center dismiss (mobile: queryAppState=" + appState + " for " + iosSessionAppBundle + ")");
						return true;
					}
				}
			} catch (Exception e) {
				Reporter.log("mobile: queryAppState failed: " + e.getMessage());
			}
		}
		return false;
	}

	private boolean iosPressHomeButton(IOSDriver iosdriver, String reason) {
		try {
			Map<String, Object> home = new HashMap<>();
			home.put("name", "home");
			iosdriver.executeScript("mobile: pressButton", home);
			Reporter.log("Pressed the Home button to dismiss Control Center (" + reason + ")");
			return true;
		} catch (Exception e) {
			Reporter.log("mobile: pressButton home failed (" + reason + "): " + e.getMessage());
			return false;
		}
	}

	private void iosFlickUpFromBottomEdgeToDismissControlCenter(IOSDriver iosdriver) {
		Dimension size = iosControlCenterWindowSize(iosdriver);
		// Start on the bottom edge (below the expanded Connectivity module, y 128-776 on
		// a 390x844 display) so the flick is a Home-indicator dismiss, not a module drag.
		int fromX = Math.max(1, size.width / 2);
		int fromY = Math.max(1, size.height - 3);
		int toX = fromX;
		int toY = Math.max(1, (int) Math.round(size.height * 0.5));
		Reporter.log("Dismiss flick up from (" + fromX + "," + fromY + ") to (" + toX + "," + toY + ") window=" + size.width + "x" + size.height);
		try {
			Map<String, Object> args = new HashMap<>();
			args.put("duration", 0.1);
			args.put("fromX", fromX);
			args.put("fromY", fromY);
			args.put("toX", toX);
			args.put("toY", toY);
			iosdriver.executeScript("mobile: dragFromToForDuration", args);
			Reporter.log("Used mobile: dragFromToForDuration (0.1s) to flick Control Center up from the bottom edge");
		} catch (Exception e) {
			Reporter.log("Bottom-edge dragFromToForDuration failed: " + e.getMessage() + "; trying a W3C 200ms flick");
			try {
				iosW3cSwipe(iosdriver, fromX, fromY, toX, toY, 200);
			} catch (Exception e2) {
				Reporter.log("W3C bottom-edge flick failed: " + e2.getMessage());
			}
		}
		iosPollFor(IOS_CC_POLL_CLOSE_MAX_MS, () -> !iosIsControlCenterOpen(iosdriver));
	}

	private String iosLastResortDismissControlCenter(IOSDriver iosdriver) {
		Dimension size = iosControlCenterWindowSize(iosdriver);
		int tapX = Math.max(1, size.width / 2);
		int tapY = Math.max(20, (int) Math.round(size.height * 0.12));
		try {
			Reporter.log("Last-resort: tapping empty header space at (" + tapX + "," + tapY + ") to dismiss Control Center");
			try {
				iosW3cTap(iosdriver, tapX, tapY);
			} catch (Exception e) {
				Reporter.log("Last-resort W3C tap failed: " + e.getMessage() + "; trying mobile: tap");
				iosTapAt(iosdriver, tapX, tapY);
			}
		} catch (Exception e) {
			Reporter.log("Last-resort header tap failed: " + e.getMessage());
		}
		if (iosPollFor(IOS_CC_POLL_CLOSE_MAX_MS, () -> !iosIsControlCenterOpen(iosdriver))) {
			return "a last-resort tap at (" + tapX + "," + tapY + ")";
		}
		iosPressHomeButton(iosdriver, "last-resort second Home press");
		iosPollFor(IOS_CC_POLL_CLOSE_MAX_MS, () -> !iosIsControlCenterOpen(iosdriver));
		return "a last-resort second Home press";
	}

	private String iosDumpControlCenterPageSource(IOSDriver iosdriver) {
		String ts = new SimpleDateFormat("yyyyMMdd_HHmmss").format(new Date());
		File out = new File(System.getProperty("user.home") + "/AppiumApps", "cc_source_" + ts + ".xml");
		try {
			if (out.getParentFile() != null) {
				out.getParentFile().mkdirs();
			}
			String source = iosdriver.getPageSource();
			FileUtils.write(out, source == null ? "" : source, "UTF-8");
			Reporter.log("Control Center page source (SpringBoard-scoped) written to " + out.getAbsolutePath());
			return out.getAbsolutePath();
		} catch (Exception e) {
			String msg = "(could not write Control Center page source: " + e.getMessage() + ")";
			Reporter.log(msg);
			return msg;
		}
	}

	private void iosControlCenterFail(Map<String, String> objDictionary, IOSDriver iosdriver, String message, boolean failIfUnavailable) {
		iosControlCenterFail(objDictionary, iosdriver, message, failIfUnavailable, null);
	}

	private void iosControlCenterFail(Map<String, String> objDictionary, IOSDriver iosdriver, String message, boolean failIfUnavailable, String sourcePath) {
		if (sourcePath != null && !sourcePath.isBlank()) {
			message = message + (message.contains(sourcePath) ? "" : " Page source saved to " + sourcePath);
		}
		Reporter.log(message);
		iosClearNetworkLastStates(objDictionary);
		if (!failIfUnavailable) {
			return;
		}
		Map<String, String> dict = objDictionary != null ? objDictionary : new HashMap<>();
		try {
			UpdateErrorMessageWithPivotalData(dict, iosdriver, message);
		} catch (Throwable ignored) {}
		throw new IllegalStateException(message);
	}

	public void SENTRYMOBILE_SET_LOCATION_MODE(Map<String, String> objDictionary) {
		String mode = objDictionary.get("strLocationServices");
		IOSDriver iosdriver = iosPreferLiveSessionDriver();
		if (!iosIsSessionAlive(iosdriver)) {
			Reporter.log("SENTRYMOBILE_SET_LOCATION_MODE skipped: Appium session is not alive (driver already quit)");
			iosClearLocationServicesLastState(objDictionary);
			return;
		}
		this.iosdriver = iosdriver;
		String gps = "Disabled".equalsIgnoreCase(mode) ? "False" : "True";
		try {
			SENTRYMOBILE_SETGPSSettings(objDictionary, iosdriver, gps, objDictionary.getOrDefault("strLocation", "43.75 -85.0"));
			iosdriver.activateApp(iosSessionAppBundle);
		} catch (RuntimeException e) {
			iosClearLocationServicesLastState(objDictionary);
			throw e;
		}
	}

